export const SEED_EVENTS: HistoricalEvent[] = [
  { id: 'great-pyramid', title: 'Great Pyramid of Giza', description: 'In the scorching heat of the Giza plateau, around 2560 BCE, tens of thousands of workers hauled 2.3 million limestone blocks — each weighing an average of 2.5 tons — to construct the most ambitious building project the ancient world had ever seen. Commissioned by Pharaoh Khufu of the Fourth Dynasty, the Great Pyramid was not merely a tomb but a cosmic machine: its four sides align almost perfectly with the cardinal directions, deviating by less than one-fifteenth of a degree, a feat of precision that still baffles engineers today.\n\nContrary to popular myth, the builders were not slaves. Archaeological evidence from nearby workers\' villages reveals they were skilled laborers organized into competing teams with names like "Friends of Khufu" and "Drunkards of Menkaure." They ate well — beef, bread, and beer — and received medical care for broken bones. The logistics alone were staggering: granite beams weighing up to 80 tons were quarried in Aswan, 800 kilometers to the south, and transported by river barge during the annual Nile flood.\n\nWhen completed, the Great Pyramid stood 146.5 meters tall, its faces sheathed in brilliant white Tura limestone that gleamed so brightly in the Egyptian sun it could be seen from miles away. For over 3,800 years, it held the record as the tallest human-made structure on Earth. Today, it is the last surviving Wonder of the Ancient World, and the only one you can still walk up to and touch — a monument so enduring that it has witnessed every major civilization that followed its creation.', year: -2560, endYear: -2540, eraId: 'ancient', latitude: 29.9792, longitude: 31.1342, category: 'construction', locationName: 'Giza, Egypt', imageUrl: 'https://images.unsplash.com/photo-1692986172150-ec32dccfa5f0?w=640&q=80&fit=crop', impactText: 'The mortar used in the Great Pyramid has been analyzed by modern chemists, but no one has been able to reproduce its exact formula — it is stronger than the stone blocks it holds together and has lasted over 4,500 years.', videoUrl: 'https://www.youtube.com/embed/fJBlEPOj4Fk', modelUrl: 'https://sketchfab.com/models/4a251113722f4d969b6cf2ca5f35c502/embed?autostart=1&ui_theme=dark' },
  { id: 'code-hammurabi', title: 'Code of Hammurabi', description: 'Around 1754 BCE, King Hammurabi of Babylon stood before a towering black diorite stele — over two meters tall and weighing four tons — and declared that the gods themselves had chosen him to bring justice to the land. Carved into this imposing stone were 282 laws that would govern every aspect of Babylonian life, from the wages of an ox-driver to the punishment for a shoddy builder whose house collapsed and killed its owner. It was not the first legal code in history, but it was by far the most comprehensive, and it announced a revolutionary idea: that the law should be written down where everyone could see it, so that "the strong should not harm the weak."\n\nThe code reveals a society far more complex than most people imagine. It regulated medical malpractice (a surgeon who blinded a patient would have his own hand cut off), set minimum wages, established consumer protection for buyers of defective goods, and even addressed the rights of women to own property and initiate divorce. Punishments were calibrated by social class — harm done to a nobleman carried stiffer penalties than the same act against a commoner — but the principle of proportional justice was groundbreaking: the punishment should fit the crime, not the whim of whoever held power.\n\nThe stele was eventually carried off as war plunder by the Elamites around 1150 BCE and taken to Susa in modern-day Iran, where French archaeologists rediscovered it in 1901. Today it stands in the Louvre in Paris, one of the most important legal documents ever created. Its influence echoes through millennia — the concept of written law, publicly displayed and applied consistently, is the bedrock on which every modern legal system rests.', year: -1754, eraId: 'ancient', latitude: 32.5421, longitude: 44.4209, category: 'political', locationName: 'Babylon, Iraq', imageUrl: 'https://images.unsplash.com/photo-1762495842622-97bf58b76181?w=640&q=80&fit=crop', impactText: 'The Code of Hammurabi includes one of history\'s first "lemon laws" — if you sold someone a defective product, you were legally required to replace it or refund the purchase price, nearly 4,000 years before modern consumer protection.', videoUrl: 'https://www.youtube.com/embed/oDALXORbtR4', modelUrl: 'https://sketchfab.com/models/44584936406a4879b8e054420dac7e07/embed?autostart=1&ui_theme=dark' },
  { id: 'trojan-war', title: 'Trojan War', description: 'For three thousand years, the Trojan War lived only in poetry — a tale of gods, heroes, and a face that launched a thousand ships. Homer\'s Iliad, composed around the 8th century BCE but describing events centuries earlier, told of a ten-year siege waged by a coalition of Greek kings against the mighty walled city of Troy, all because the Trojan prince Paris had stolen Helen, the most beautiful woman in the world, from her husband King Menelaus of Sparta. It was a story so vivid that the ancient Greeks never doubted it was real.\n\nThen, in the 1870s, a self-taught German archaeologist named Heinrich Schliemann did the unthinkable: he took Homer literally and started digging. At Hisarlik in northwestern Turkey, he unearthed the ruins of not one but nine cities built on top of each other, spanning millennia. Layer VIIa, dating to around 1180 BCE, showed clear signs of violent destruction — charred walls, scattered arrowheads, and hastily abandoned streets. The archaeological world was electrified. Troy was real. Whether Helen was real, whether there was truly a hollow wooden horse, remains unknown — but a great and wealthy city at the crossroads of East and West had indeed been besieged and burned.\n\nThe legacy of the Trojan War extends far beyond archaeology. It gave Western literature its founding masterpiece, shaped Greek identity for centuries, and introduced archetypes — the cunning Odysseus, the wrathful Achilles, the doomed Hector — that still resonate in every war story told today. The very idea of a "Trojan horse" remains our go-to metaphor for hidden threats. Real or mythologized, the war at Troy is the story where history and storytelling first became inseparable.', year: -1200, eraId: 'ancient', latitude: 39.9575, longitude: 26.2389, category: 'war', locationName: 'Troy, Turkey', imageUrl: 'https://images.unsplash.com/photo-1748884731434-c3d6369c9d0e?w=640&q=80&fit=crop', impactText: 'When Heinrich Schliemann excavated Troy in the 1870s, he found a cache of gold jewelry he called "Priam\'s Treasure." He smuggled it out of the Ottoman Empire in his wife\'s shawl — it vanished during WWII and was secretly kept in Moscow until Russia admitted to having it in 1993.', videoUrl: 'https://www.youtube.com/embed/gQbZX9JEQsQ', modelUrl: 'https://sketchfab.com/models/6d05805e104c40cbb8664d9c7c460300/embed?autostart=1&ui_theme=dark' },
  { id: 'founding-rome', title: 'Founding of Rome', description: 'The story Rome told about itself was soaked in blood from the very beginning. According to legend, twin brothers Romulus and Remus — sons of the war god Mars, suckled by a she-wolf on the banks of the Tiber — quarreled over where to build their new city. When Remus mocked his brother by jumping over the low walls Romulus had begun to raise on the Palatine Hill, Romulus killed him, declaring: "So perish anyone who shall hereafter leap over my walls." On April 21, 753 BCE, Rome was founded in fratricide — and it would grow into the most powerful city the ancient world had ever known.\n\nArchaeology partially supports the legend\'s timeline. Excavations on the Palatine Hill have uncovered hut foundations and pottery dating to the mid-8th century BCE, suggesting that a small settlement of Latin shepherds and farmers did indeed cluster on Rome\'s famous seven hills around this time. The early Romans were an unremarkable people surrounded by far more sophisticated neighbors — the Etruscans to the north, the Greek colonies to the south. Yet within five centuries, this village of thatched huts would conquer the entire Italian peninsula, and within eight, it would rule an empire stretching from Britain to Mesopotamia.\n\nWhat made Rome extraordinary was not its origin but its ambition. The Romans absorbed every culture they conquered — Etruscan engineering, Greek philosophy, Egyptian religion — and forged it all into something new. Their roads, laws, language, and architecture would outlast the empire itself. When you drive on a paved road, watch a trial by jury, or read a language descended from Latin, you are touching something that traces back to a cluster of mud huts on a hill beside the Tiber, where a legendary founder chose violence and vision in equal measure.', year: -753, eraId: 'ancient', latitude: 41.9028, longitude: 12.4964, category: 'political', locationName: 'Rome, Italy', imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/de/Colosseo_2020.jpg/960px-Colosseo_2020.jpg', impactText: 'The traditional date of Rome\'s founding — April 21, 753 BCE — is still celebrated today as "Natale di Roma" (Rome\'s Birthday), with costumed parades of gladiators and legionaries marching through the ancient city center every year.', videoUrl: 'https://www.youtube.com/embed/8NGBG5pKAAY', modelUrl: 'https://sketchfab.com/models/f03fa209176e4659abc7c5b31730a5a5/embed?autostart=1&ui_theme=dark' },
  { id: 'democracy-athens', title: 'Birth of Democracy', description: 'In 508 BCE, Athens was teetering on the edge of tyranny. A power struggle among aristocratic families threatened to plunge the city into civil war. Into this chaos stepped Cleisthenes, an unlikely reformer from one of Athens\' most powerful families, who proposed something radical: instead of letting the nobility fight over who would rule, why not let the people decide? He reorganized Athenian society from the ground up, breaking the power of the old tribal aristocracies by creating ten new "tribes" that mixed citizens from different regions, ensuring no single faction could dominate.\n\nThe system Cleisthenes built was astonishingly direct. There was no representative government, no parliament — every male citizen over 18 could speak and vote in the Assembly (Ekklesia), which met on a hillside called the Pnyx with a quorum of 6,000. Citizens voted on everything from tax policy to declarations of war by raising their hands. Juries numbered in the hundreds to prevent bribery. Officials were chosen by lottery rather than election, on the theory that elections favored the rich and well-connected while random selection gave every citizen an equal chance to serve. It was messy, noisy, and revolutionary.\n\nAthenian democracy was far from perfect by modern standards — women, slaves, and foreigners were excluded, meaning only about 10-20% of the population could participate. But the core idea was explosive: that ordinary people, not kings or priests, had the wisdom and the right to govern themselves. This experiment lasted nearly two centuries and produced an extraordinary cultural flowering — the philosophy of Socrates and Plato, the tragedies of Sophocles, the Parthenon itself. The word "democracy" — from demos (people) and kratos (power) — was born here, and it would take over two thousand years for the rest of the world to catch up.', year: -508, eraId: 'classical', latitude: 37.9838, longitude: 23.7275, category: 'political', locationName: 'Athens, Greece', imageUrl: 'https://images.unsplash.com/photo-1569770725012-58fac5eec229?w=640&q=80&fit=crop', impactText: 'Athenian democracy had a unique safety valve called "ostracism" — citizens could vote to banish any person they considered too powerful by scratching a name on a pottery shard (ostrakon). The "winner" was exiled from Athens for ten years.', videoUrl: 'https://www.youtube.com/embed/0fivQUlC7-8', modelUrl: 'https://sketchfab.com/models/fa23b514e7564ebca473d7e041a07118/embed?autostart=1&ui_theme=dark' },
  { id: 'roman-forum', title: 'Roman Forum Inauguration', description: 'Before it became the nerve center of an empire, the Roman Forum was a swamp. The marshy valley between the Palatine and Capitoline hills was transformed around 500 BCE when the Romans — possibly under the Etruscan kings — built the Cloaca Maxima, one of the world\'s earliest sewage systems, to drain the waterlogged ground. What emerged was a public square that would serve as the beating heart of Roman civilization for nearly a thousand years: a place where senators debated the fate of nations, generals paraded their conquests, merchants hawked their goods, and ordinary citizens gathered to hear the news of the day.\n\nAt its peak, the Forum was a dazzling architectural showcase. The Temple of Saturn housed the state treasury. The Rostra — a speaker\'s platform decorated with the bronze prows of captured warships — was where Cicero delivered his thundering orations and where Mark Antony held up Caesar\'s bloodied toga to whip a crowd into fury. The Via Sacra, Rome\'s oldest street, cut through its center, serving as the route for triumphal processions in which victorious generals rode chariots past cheering crowds, their faces painted red in imitation of Jupiter himself. Every major event in Roman public life — elections, trials, funerals of great men, religious festivals — happened here.\n\nAfter the fall of Rome, the Forum was gradually buried under centuries of debris, its marble temples quarried for building material, its grand spaces converted into cattle pastures. By the Middle Ages, Romans called it the "Campo Vaccino" — the cow field. It was not until the 18th and 19th centuries that systematic excavation began to reveal the ruins we see today, a haunting skeleton of columns and arches that still conveys the grandeur of the civilization that built it.', year: -500, eraId: 'classical', latitude: 41.8925, longitude: 12.4853, category: 'cultural', locationName: 'Rome, Italy', imageUrl: 'https://images.unsplash.com/photo-1727407469678-a8a92ea66731?w=640&q=80&fit=crop', impactText: 'The Forum\'s drainage system, the Cloaca Maxima, was so well engineered that parts of it are still functioning today — over 2,500 years after construction — carrying storm water through Rome and emptying into the Tiber River.', modelUrl: 'https://sketchfab.com/models/577d9077f4374e79b6061e30650a3c4e/embed?autostart=1&ui_theme=dark' },
  { id: 'alexander-empire', title: 'Alexander the Great\'s Empire', description: 'When Alexander III of Macedon inherited his father\'s throne in 336 BCE at the age of twenty, he was already a battle-tested warrior who had been tutored by Aristotle himself. Within just thirteen years, he would conquer the largest empire the world had ever seen — a domain stretching from Greece to the borders of India, encompassing Egypt, Persia, Mesopotamia, and Central Asia. He never lost a single battle. His military genius was matched by breathtaking personal courage; at the siege of Multan in India, he leaped alone from a scaling ladder into the enemy fortress, fighting surrounded until his men smashed through the walls to reach him. He nearly died from an arrow that punctured his lung.\n\nAlexander did not merely conquer — he transformed. He founded over twenty cities bearing his name, the most famous being Alexandria in Egypt, which became the intellectual capital of the ancient world and home to the legendary Library. He encouraged his soldiers to marry local women and adopted Persian court customs, envisioning a fusion of Greek and Eastern cultures that historians call the Hellenistic world. Greek became the lingua franca from the Mediterranean to Afghanistan. Greek art merged with Buddhist traditions in Gandhara, producing some of the first images of the Buddha. The cultural ripple effects of his conquests lasted centuries.\n\nAlexander died in Babylon on June 10, 323 BCE, at the age of 32 — possibly from typhoid fever complicated by alcoholism, though poisoning theories persist to this day. When asked on his deathbed to whom he left his empire, he reportedly whispered, "To the strongest." His generals promptly tore the empire apart in a series of wars that carved the ancient world into rival kingdoms. But the Hellenistic civilization he sparked would endure until Rome swallowed it whole, and the Greek cultural influence he spread would form one of the foundation stones of Western civilization.', year: -323, eraId: 'classical', latitude: 40.6401, longitude: 22.9444, category: 'political', locationName: 'Thessaloniki, Greece', imageUrl: 'https://images.unsplash.com/photo-1632074869310-306c1a1ed874?w=640&q=80&fit=crop', impactText: 'Alexander\'s body was preserved in a gold coffin filled with honey and displayed in Alexandria for centuries. Roman emperors including Augustus and Caligula made pilgrimages to visit it. The tomb was eventually lost — and despite countless searches, no one has ever found it.', videoUrl: 'https://www.youtube.com/embed/bVjKL1zd-vQ', modelUrl: 'https://sketchfab.com/models/5a496592be8a4e58bd1dfc0ac7c6ae46/embed?autostart=1&ui_theme=dark' },
  { id: 'great-wall-begin', title: 'Great Wall Construction Begins', description: 'In 221 BCE, Emperor Qin Shi Huang had just accomplished what no one had managed in five centuries of constant warfare: he unified the seven warring states of China into a single empire. But his northern frontier was terrifyingly vulnerable to mounted nomadic raiders — the Xiongnu, whose horseback cavalry could strike deep into Chinese territory and vanish before any army could respond. Qin\'s solution was as ambitious as it was brutal: connect and extend the scattered defensive walls that earlier states had built into one continuous fortification across the entire northern border. Hundreds of thousands of conscripted laborers, soldiers, and convicts were marched to the frontier to begin the work.\n\nThe human cost was staggering. Workers toiled in extreme conditions — scorching deserts, frozen mountain passes, and remote grasslands far from home. Food was scarce, conditions were harsh, and the dead were sometimes buried within the wall itself. Chinese folklore calls it "the longest cemetery on Earth." Yet the engineering was remarkable: the wall followed the contours of ridgelines for maximum defensive advantage, incorporating watchtowers every few hundred meters that could relay smoke signals across hundreds of kilometers in hours — an ancient early-warning system that could mobilize armies faster than any messenger on horseback.\n\nWhat most people picture as "The Great Wall" — the imposing stone-and-brick fortification snaking across mountaintops — is mostly the Ming Dynasty reconstruction from the 14th-17th centuries CE. But the project Qin Shi Huang began in 221 BCE established the concept and the route. A comprehensive archaeological survey completed in 2012 measured the total length of all wall sections ever built at 21,196 kilometers — more than half the circumference of the Earth. It remains the largest construction project in human history, a monument to both extraordinary human achievement and extraordinary human suffering.', year: -221, eraId: 'classical', latitude: 40.4319, longitude: 116.5704, category: 'construction', locationName: 'Beijing, China', imageUrl: 'https://images.unsplash.com/photo-1508804185872-d7badad00f7d?w=640&q=80&fit=crop', impactText: 'Despite the popular myth, the Great Wall of China is NOT visible from space with the naked eye — astronauts have confirmed it is too narrow. However, the wall\'s watchtower smoke-signal system could transmit a message across the entire frontier in just a few hours, faster than any horse.', videoUrl: 'https://www.youtube.com/embed/23oHqNEqRyo', modelUrl: 'https://sketchfab.com/models/eb94be2c56a14f009e6f0f2533c996d7/embed?autostart=1&ui_theme=dark' },
  { id: 'julius-caesar', title: 'Assassination of Julius Caesar', description: 'On the morning of March 15, 44 BCE — the Ides of March — Gaius Julius Caesar walked into a meeting of the Roman Senate at the Theatre of Pompey. He had been warned. His wife Calpurnia had begged him not to go, troubled by nightmares. A soothsayer had famously cautioned him to "beware the Ides of March." But Caesar, who had conquered Gaul, crossed the Rubicon, defeated Pompey in civil war, and been declared dictator perpetuo (dictator for life), was not a man given to fear. He waved away his concerns and entered the Senate without his bodyguards.\n\nWhat happened next was swift and savage. As Caesar took his seat, a senator named Tillius Cimber approached with a petition, grabbing Caesar\'s toga and pulling it from his shoulder — the signal. Casca struck the first blow from behind, a clumsy slash to the neck. Caesar spun around, grabbing Casca\'s arm and stabbing him with his stylus, shouting "Casca, you villain!" But then the others closed in — Brutus, Cassius, and at least twenty more conspirators, all drawing concealed daggers. Caesar fought back briefly but was overwhelmed. Ancient sources claim he received 23 stab wounds. He collapsed and died at the base of a statue of his old rival Pompey, his blood pooling on the marble floor of the Senate.\n\nThe conspirators, who called themselves the Liberatores, believed they were saving the Roman Republic from a tyrant. They were catastrophically wrong. Caesar\'s assassination did not restore the Republic — it destroyed it. The power vacuum triggered another round of devastating civil wars that would claim the lives of nearly all the conspirators and ultimately hand absolute power to Caesar\'s adopted heir, the 18-year-old Octavian, who would become Augustus, the first Roman Emperor. The Republic the assassins had killed to protect died with their victim.', year: -44, eraId: 'classical', latitude: 41.8955, longitude: 12.4823, category: 'political', locationName: 'Rome, Italy', imageUrl: 'https://images.unsplash.com/photo-1666714049828-502a027b27dc?w=640&q=80&fit=crop', impactText: 'Caesar was so beloved by the common people that when his body was cremated in the Forum, the crowd was so frenzied with grief that they tore apart nearby buildings to feed the funeral pyre. A comet appeared in the sky shortly after, which Romans believed was Caesar\'s soul ascending to godhood.', videoUrl: 'https://www.youtube.com/embed/wgPymD-NBQU', modelUrl: 'https://sketchfab.com/models/16eea6a1895948cdb2f610e72a6d6e9c/embed?autostart=1&ui_theme=dark' },
  { id: 'colosseum', title: 'Colosseum Completed', description: 'When Emperor Vespasian began construction of the Flavian Amphitheatre in 72 CE, he chose the site with calculated political genius: the private pleasure lake of the despised Emperor Nero\'s Golden Palace. Where a tyrant had built himself a playground, Vespasian would give the Roman people the greatest entertainment venue the world had ever seen. Eight years and tens of thousands of workers later, his son Titus inaugurated the completed Colosseum in 80 CE with 100 consecutive days of games in which, according to the ancient historian Cassius Dio, over 9,000 wild animals were killed and thousands of gladiators fought.\n\nThe engineering was centuries ahead of its time. The elliptical structure stood 48 meters tall — roughly the height of a modern 15-story building — and could seat between 50,000 and 80,000 spectators. An ingenious system of numbered arches and staircases (vomitoria) could fill or empty the entire arena in minutes, a crowd-flow design that modern stadium architects still study. A massive retractable awning called the velarium, operated by a detachment of sailors from the Roman navy, shielded spectators from the sun. Beneath the arena floor lay the hypogeum — a labyrinth of tunnels, cages, and mechanical elevators that could raise wild animals, scenery, and combatants dramatically into the arena through trapdoors.\n\nThe spectacles held here were both magnificent and horrifying. Gladiatorial combat, wild beast hunts (venationes), public executions, and even re-enactments of famous battles drew crowds from across the empire. In the early years, the arena may have been flooded for staged naval battles (naumachiae). The Colosseum remained in active use for over four centuries, surviving earthquakes and fires. Today, roughly two-thirds of the original structure has been destroyed by earthquakes and stone-robbers, yet what remains is still the most iconic symbol of Imperial Rome — and the direct ancestor of every sports stadium on Earth.', year: 80, eraId: 'classical', latitude: 41.8902, longitude: 12.4922, category: 'construction', locationName: 'Rome, Italy', imageUrl: 'https://images.unsplash.com/photo-1515542483964-5e8c63d7d89b?w=640&q=80&fit=crop', impactText: 'The Colosseum\'s hypogeum (underground network) contained 80 vertical shafts with elevator platforms powered by human-operated winches — allowing lions, bears, and even elephants to appear as if rising magically from the arena floor.', videoUrl: 'https://www.youtube.com/embed/TB5weRIYhjQ', modelUrl: 'https://sketchfab.com/models/535dc96e586f40bd956ea3cbff810055/embed?autostart=1&ui_theme=dark' },
  { id: 'fall-of-rome', title: 'Fall of the Western Roman Empire', description: 'On September 4, 476 CE, a teenage boy named Romulus Augustulus — whose very name was a cruel irony, combining Rome\'s legendary founder with its first emperor — was quietly deposed by the Germanic warlord Odoacer. There was no great battle, no dramatic last stand. The last Western Roman Emperor was simply told to step aside, given a pension, and sent to live in a villa in Campania. The empire that had ruled the Western world for five centuries ended not with a bang but with a bureaucratic shrug. Most people living at the time barely noticed.\n\nThe "fall" had been centuries in the making. By the 5th century, the Western Empire was a hollow shell. Decades of civil wars, economic collapse, plague, and the relentless pressure of Germanic migrations had gutted its military and administrative capacity. The once-mighty legions were now largely composed of Germanic mercenaries whose loyalty was to their own chiefs, not to Rome. The city of Rome itself had been sacked twice — by the Visigoths under Alaric in 410 CE and by the Vandals in 455 CE — events that sent shockwaves of horror across the Mediterranean world. Saint Jerome, writing from Bethlehem, wept: "The city which had taken the whole world was itself taken."\n\nHistorians have proposed over 200 different theories for why Rome fell — from lead poisoning to moral decay to climate change. The truth is likely a perfect storm of interconnected crises. But what matters most is what came after. The fall of Rome did not plunge Europe into immediate "darkness." Roman institutions, language, law, and Christianity persisted and transformed. The Eastern Roman Empire — Byzantium — would survive for nearly another thousand years. But the political unity of the Western Mediterranean was shattered, and the fragmented world that emerged — of competing kingdoms, feudal lords, and a powerful Church — would define the medieval era for the next millennium.', year: 476, eraId: 'classical', latitude: 41.9028, longitude: 12.4964, category: 'political', locationName: 'Rome, Italy', imageUrl: 'https://images.unsplash.com/photo-1767722413124-fd36f807b6b3?w=640&q=80&fit=crop', impactText: 'The last Western Roman Emperor\'s name, Romulus Augustulus ("little Augustus"), combined the names of Rome\'s legendary founder and its first emperor — as if history were writing its own poetic bookend to a civilization that lasted over a thousand years.', videoUrl: 'https://www.youtube.com/embed/3PszVWZNWVA' },
  { id: 'hagia-sophia', title: 'Hagia Sophia Completed', description: 'When Emperor Justinian I stepped through the doors of his completed cathedral on December 27, 537 CE, he allegedly whispered, "Solomon, I have surpassed thee" — comparing his achievement to the legendary Temple of Jerusalem. He was not exaggerating. The Hagia Sophia (Holy Wisdom) was unlike anything the world had ever seen: a vast interior space crowned by a dome that seemed to float unsupported in the air, 55 meters above the marble floor, pierced by a ring of forty windows that poured light into the nave like a golden halo. Visitors described the experience as stepping into heaven itself.\n\nThe engineering behind this miracle was revolutionary. Justinian\'s architects, Anthemius of Tralles and Isidorus of Miletus, were not traditional builders but mathematicians who essentially invented a new structural system. The massive central dome, 31 meters in diameter, is supported not by thick walls but by a series of pendentives — curved triangular surfaces that transfer the dome\'s weight to four massive piers. This solution to the problem of placing a round dome on a square base was so elegant that it influenced virtually every large domed building constructed afterward, from the Blue Mosque next door to the U.S. Capitol building in Washington. The interior was covered in over 30 million gold mosaic tiles, and the marble was quarried from across the empire — green from Thessaly, purple from Phrygia, white from the Marmara islands.\n\nFor 916 years, the Hagia Sophia served as the world\'s largest cathedral and the spiritual heart of Eastern Orthodox Christianity. When the Ottoman Sultan Mehmed II conquered Constantinople in 1453, he was so awestruck by the building that he immediately ordered it preserved and converted into a mosque, adding minarets and Islamic calligraphy to the interior while leaving the Christian mosaics largely intact behind plaster. Today, after serving as a museum from 1934 to 2020 and then reconverted to a mosque, it remains one of the most extraordinary buildings ever constructed — a living testament to two great civilizations.', year: 537, eraId: 'medieval', latitude: 41.0086, longitude: 28.9802, category: 'construction', locationName: 'Istanbul, Turkey', imageUrl: 'https://images.unsplash.com/photo-1683874350903-8151d987fef4?w=640&q=80&fit=crop', impactText: 'The original dome of the Hagia Sophia partially collapsed in an earthquake just 21 years after completion. It was rebuilt 6 meters higher and slightly steeper — and that rebuilt dome has stood for over 1,400 years, surviving more than 50 significant earthquakes.', videoUrl: 'https://www.youtube.com/embed/KRPp3jzv1Tw', modelUrl: 'https://sketchfab.com/models/7e7d826a49d248a7a81d4129ce976420/embed?autostart=1&ui_theme=dark' },
  { id: 'viking-expansion', title: 'Viking Expansion Begins', description: 'On June 8, 793 CE, a group of Norse warriors sailed out of the morning mist and fell upon the monastery of Lindisfarne, a tiny tidal island off the northeast coast of England. The monks — who had lived there in peaceful scholarship for over a century, producing masterpieces like the Lindisfarne Gospels — were utterly unprepared. The raiders killed some, enslaved others, and plundered the monastery\'s treasures of gold, silver, and jeweled reliquaries. The Anglo-Saxon scholar Alcuin, writing from the court of Charlemagne, was horrified: "Never before has such terror appeared in Britain. The church of St. Cuthbert is spattered with the blood of the priests of God."\n\nThe attack on Lindisfarne was not the first Viking raid, but it was the one that shattered the complacency of Christian Europe and announced the beginning of the Viking Age. Over the next three centuries, Norse seafarers would reshape the map of the world. They conquered and settled large swaths of England (the Danelaw), colonized Normandy in France (the Normans were literally "North-men"), established the Rus\' state that became Russia, traded along rivers deep into Central Asia, raided as far as Constantinople and North Africa, and settled Iceland, Greenland, and — around 1000 CE — became the first Europeans to reach North America, nearly five centuries before Columbus.\n\nWhat drove the Viking expansion remains debated: population pressure, political upheaval in Scandinavia, technological superiority in shipbuilding, or simply the lure of silver and glory. Their longships were engineering marvels — shallow-drafted enough to navigate rivers yet seaworthy enough to cross the open Atlantic, with a single square sail and a hull of overlapping oak planks so flexible it could ride ocean swells like a living creature. The Vikings were not merely raiders but also traders, explorers, poets, and state-builders whose three-century eruption permanently reshaped Europe, Russia, and the North Atlantic world.', year: 793, eraId: 'medieval', latitude: 55.6689, longitude: -1.7847, category: 'war', locationName: 'Lindisfarne, England', imageUrl: 'https://images.unsplash.com/photo-1761570365095-f0ad45de3bd1?w=640&q=80&fit=crop', impactText: 'Viking longships were so shallow-drafted (as little as 50 cm) that they could sail up rivers and even be carried overland between waterways. Using this technique, Swedish Vikings sailed from the Baltic Sea all the way to Constantinople via Russian rivers — a journey of over 2,500 kilometers.', videoUrl: 'https://www.youtube.com/embed/kge0c2mNmRQ', modelUrl: 'https://sketchfab.com/models/3df33988491a4390a4223907c0b08d58/embed?autostart=1&ui_theme=dark' },
  { id: 'house-of-wisdom', title: 'House of Wisdom Founded', description: 'In the early 9th century, Caliph Harun al-Rashid and his son al-Ma\'mun transformed Baghdad into the intellectual capital of the world by establishing the Bayt al-Hikma — the House of Wisdom. What began as a modest royal library grew into the greatest center of learning the medieval world had ever seen: a vast institution where scholars from across the Islamic world, as well as Christian, Jewish, Zoroastrian, and Hindu thinkers, gathered to translate, study, and expand upon the accumulated knowledge of every civilization they could reach. The scale of the translation effort was staggering — entire libraries of Greek, Persian, Sanskrit, and Syriac texts were systematically rendered into Arabic, preserving works by Aristotle, Euclid, Galen, and Ptolemy that would otherwise have been lost to history forever.\n\nThe House of Wisdom was far more than a translation bureau. It was a research university centuries before Europe invented the concept. The mathematician al-Khwarizmi worked there, writing the treatise "Al-Jabr" that gave algebra its name and introducing the Hindu-Arabic numeral system — including the concept of zero — that would eventually replace Roman numerals across the world. The polymath al-Kindi pioneered cryptanalysis and frequency analysis. Hunayn ibn Ishaq translated over 100 medical texts and wrote original works on ophthalmology. Astronomers at the institution calculated the circumference of the Earth to within 1% of the modern value, and their star catalogues remained standard references for 500 years.\n\nThe destruction of the House of Wisdom during the Mongol sack of Baghdad in 1258 is one of history\'s greatest cultural catastrophes. Legend holds that the Tigris River ran black with ink from the thousands of manuscripts thrown into its waters. The loss was incalculable — centuries of accumulated knowledge obliterated in days. Yet the institution\'s legacy had already seeded the European Renaissance: Arabic translations of Greek philosophy, transmitted through Islamic Spain, would ignite the intellectual revolution that transformed medieval Europe into the modern world.', year: 830, eraId: 'medieval', latitude: 33.3152, longitude: 44.3661, category: 'cultural', locationName: 'Baghdad, Iraq', imageUrl: 'https://images.unsplash.com/photo-1577561426384-62154a1e9457?w=640&q=80&fit=crop', impactText: 'The word "algorithm" comes directly from the Latinized name of al-Khwarizmi, a mathematician at the House of Wisdom. The word "algebra" comes from his book title "Al-Jabr." Every time you use either term, you are speaking Arabic.' },
  { id: 'song-dynasty-movable-type', title: 'Song Dynasty Invents Movable Type', description: 'Around 1040 CE, during the golden age of the Song Dynasty, a humble artisan named Bi Sheng devised a system that would anticipate one of history\'s most transformative technologies by four centuries. Working in his workshop in Yingshan, Bi Sheng carved individual Chinese characters into small blocks of baked clay, arranged them on an iron plate coated with a mixture of pine resin, wax, and paper ash, and used this ingenious system to print multiple copies of texts far faster than traditional woodblock printing allowed. When a page was finished, the plate was gently heated to melt the adhesive, the type was removed, sorted, and stored for reuse. It was the world\'s first movable type printing system — 400 years before Gutenberg.\n\nThe Song Dynasty was arguably the most technologically advanced civilization on Earth at this time. With a population exceeding 100 million and an economy driven by the world\'s first paper currency, Song China was an incubator of innovation on a scale unmatched anywhere else. Gunpowder, originally a Taoist alchemical accident, was refined into devastating military weapons — fire lances, bombs, and early rockets. The magnetic compass, initially used for feng shui divination, was adapted for maritime navigation, enabling Song merchant fleets to dominate trade routes from Japan to the Persian Gulf. The iron and steel industry produced quantities not matched in Europe until the 18th century.\n\nBi Sheng\'s movable type, though revolutionary in concept, faced a practical limitation that woodblock printing did not: the Chinese writing system uses thousands of distinct characters, making it far more complex to manage than a 26-letter alphabet. For this reason, woodblock printing remained dominant in China for centuries. But the idea traveled westward along the Silk Road, and when Johannes Gutenberg independently developed his own movable metal type in the 1440s — using an alphabet with far fewer characters — it ignited the information revolution that reshaped Europe and eventually the world.', year: 1040, eraId: 'medieval', latitude: 34.7972, longitude: 114.3076, category: 'discovery', locationName: 'Kaifeng, China', imageUrl: 'https://images.unsplash.com/photo-1671041990288-1c40505a1e07?w=640&q=80&fit=crop', impactText: 'The Song Dynasty produced more iron per year in the 11th century than the whole of Great Britain produced at the start of its Industrial Revolution in 1788 — a fact that has led historians to ask why China did not industrialize first.' },
  { id: 'battle-of-hastings', title: 'Battle of Hastings', description: 'On the morning of October 14, 1066, two armies faced each other on Senlac Hill near the town of Hastings in southern England, and the outcome of the battle fought that day would alter the course of English history more profoundly than any event before or since. On one side stood Harold Godwinson, the last Anglo-Saxon King of England, his army of housecarls and fyrd militia still exhausted from a forced march south after defeating a Norwegian invasion at Stamford Bridge just nineteen days earlier. On the other stood William, Duke of Normandy, who had crossed the English Channel with roughly 7,000 men and a papal banner blessing his claim to the English throne.\n\nThe battle raged for nine brutal hours — extraordinarily long by medieval standards. Harold\'s infantry, fighting on foot behind a shield wall on the high ground, initially repulsed William\'s cavalry charges. The turning point came when groups of Norman horsemen feigned retreat, drawing undisciplined English soldiers down the hill in pursuit, where they were cut to pieces. As evening fell, an arrow — or perhaps a lance thrust, accounts differ — struck Harold in or near the eye. The king fell, his bodyguard was slaughtered around him, and the English army broke. By nightfall, the Anglo-Saxon world that had endured for six centuries was effectively over.\n\nWilliam\'s conquest transformed England utterly. Within two decades, virtually the entire Anglo-Saxon aristocracy was replaced by a French-speaking Norman elite. The English language itself was reshaped: common folk still spoke Old English while their rulers spoke Norman French, and when the two merged over centuries, the result was Middle English — the hybrid tongue that would eventually become the most widely spoken language on Earth. William ordered the Domesday Book, a comprehensive survey of every landholding in England that remains an invaluable historical record. He built the Tower of London and introduced the feudal system that would define English society for four hundred years.', year: 1066, eraId: 'medieval', latitude: 50.9144, longitude: 0.4878, category: 'war', locationName: 'Hastings, England', imageUrl: 'https://images.unsplash.com/photo-1485465053475-dd55ed3894b9?w=640&q=80&fit=crop', impactText: 'The Bayeux Tapestry, which depicts the Battle of Hastings in 70 meters of embroidered linen, is essentially a medieval comic strip — and it contains the first known depiction of Halley\'s Comet, which appeared in 1066 and was taken as an omen of Harold\'s doom.', videoUrl: 'https://www.youtube.com/embed/Jl3K63Rbygw', modelUrl: 'https://sketchfab.com/models/a9d3d773a9f24980a06eba2d056f5d7d/embed?autostart=1&ui_theme=dark' },
  { id: 'first-crusade', title: 'First Crusade — Siege of Jerusalem', description: 'On July 15, 1099, after a five-week siege in the scorching heat of a Palestinian summer, Crusader soldiers breached the walls of Jerusalem. What followed was one of the most notorious massacres in medieval history. The knights and foot soldiers who poured through the gaps slaughtered virtually everyone they found — Muslim men, women, and children were cut down in the streets and in the al-Aqsa Mosque, where the blood reportedly ran ankle-deep. The Jewish population, who had taken refuge in the Great Synagogue, was burned alive when the Crusaders set the building on fire. By the time the killing stopped, an estimated 40,000 people lay dead in the holy city that three religions called sacred.\n\nThe First Crusade had begun three years earlier, on November 27, 1095, when Pope Urban II delivered a thundering speech at the Council of Clermont in France, calling on Christian warriors to march east and reclaim the Holy Land from Muslim rule. The response was staggering: an estimated 60,000 to 100,000 people — nobles, knights, peasants, and even entire families — set out on the 3,000-kilometer journey to Jerusalem. They endured famine, disease, brutal battles at Nicaea and Antioch, and the merciless heat of the Levantine desert. Roughly one in four survived to reach Jerusalem\'s walls.\n\nThe Crusaders established the Kingdom of Jerusalem and three other Crusader states that would endure for nearly two centuries, creating a unique hybrid culture where Frankish knights adopted local customs, ate Middle Eastern food, and sometimes allied with Muslim neighbors against common enemies. But the legacy of the Crusades would poison Christian-Muslim relations for a millennium. The word "Crusade" itself remains politically charged in the Middle East today. The eventual Muslim reconquest under Saladin in 1187 — conducted with conspicuous mercy as a deliberate contrast to the 1099 massacre — set the stage for seven more Crusades, none of which would match the devastating success of the first.', year: 1099, eraId: 'medieval', latitude: 31.7767, longitude: 35.2345, category: 'war', locationName: 'Jerusalem, Israel', imageUrl: 'https://images.unsplash.com/photo-1573322867455-fc97c490c14c?w=640&q=80&fit=crop', impactText: 'The Crusades accidentally introduced Europeans to dozens of "exotic" goods that became staples of Western life — including sugar, cotton, silk, spices, lemons, apricots, rice, and even windmills, which Crusaders first encountered in the Middle East.', videoUrl: 'https://www.youtube.com/embed/X0zudTQelzI', modelUrl: 'https://sketchfab.com/models/48fdc77fd18148938a2de1c4ded8cc1e/embed?autostart=1&ui_theme=dark' },
  { id: 'angkor-wat', title: 'Angkor Wat Completed', description: 'Rising from the tropical forests of northwestern Cambodia, Angkor Wat is the largest religious monument ever constructed by human hands. Built over approximately 30 years during the reign of King Suryavarman II of the Khmer Empire, this vast temple complex was dedicated to the Hindu god Vishnu and designed as a symbolic representation of Mount Meru, the sacred mountain at the center of the universe in Hindu cosmology. Its five iconic lotus-bud towers rise to 65 meters, surrounded by a moat 190 meters wide that stretches 5.5 kilometers around the entire complex — an engineering feat that required moving more stone than the Great Pyramid of Giza.\n\nThe scale of Angkor Wat defies comprehension. The temple sits within an outer wall measuring 1,024 by 802 meters, encompassing an area of 162 hectares. Its walls are covered with nearly 2,000 square meters of intricate bas-relief carvings — the longest continuous bas-relief in the world — depicting scenes from Hindu mythology, epic battles, and daily life in the Khmer Empire. One gallery alone shows the Churning of the Ocean of Milk, with 88 devas and 92 asuras pulling a giant serpent in a cosmic tug-of-war. The level of detail is astonishing: individual soldiers are carved with distinct facial expressions, and apsara dancers wear unique costumes and jewelry. An estimated 300,000 workers and 6,000 elephants were needed to quarry and transport the sandstone blocks from a mountain 50 kilometers away.\n\nAt its peak in the 12th and 13th centuries, the city of Angkor surrounding the temple was the largest urban center on Earth, home to roughly 750,000 to 1,000,000 people — at a time when London had barely 50,000. The Khmer engineered a sophisticated water management system of reservoirs and canals that sustained intensive rice agriculture capable of feeding this enormous population. When the empire declined and the city was gradually abandoned after the 15th century, the jungle reclaimed it. Angkor Wat was never entirely forgotten — Buddhist monks maintained parts of the complex — but it was not until French explorers publicized it in the 1860s that the Western world discovered what remains one of humanity\'s most breathtaking architectural achievements.', year: 1150, eraId: 'medieval', latitude: 13.4125, longitude: 103.8670, category: 'construction', locationName: 'Siem Reap, Cambodia', imageUrl: 'https://images.unsplash.com/photo-1554481923-a6918bd997bc?w=640&q=80&fit=crop', impactText: 'The moat around Angkor Wat is not merely decorative — it serves a critical structural function by stabilizing the water table beneath the temple, preventing the sandy soil from shifting. Without it, the massive structure would likely have collapsed centuries ago.', modelUrl: 'https://sketchfab.com/models/86a97678ae6d4f41a14c13d77990f223/embed?autostart=1&ui_theme=dark' },
  { id: 'genghis-khan', title: 'Mongol Empire Founded', description: 'In 1206, on the banks of the Onon River in the wind-scoured steppe of Mongolia, a gathering of tribal chiefs proclaimed a man named Temujin as "Genghis Khan" — Universal Ruler. He was around 44 years old, and his life until that point had been a brutal odyssey of survival: kidnapped as a child, enslaved as a teenager, betrayed by allies, and forced to claw his way to power through two decades of steppe warfare. But Temujin possessed a rare combination of military genius, political cunning, and organizational brilliance that would make him the most consequential conqueror in human history.\n\nGenghis Khan\'s military innovations were devastating. He organized his army on a decimal system — units of 10, 100, 1,000, and 10,000 — cutting across tribal loyalties to forge a unified fighting force of unprecedented discipline. Mongol cavalry could cover 100 kilometers in a single day, communicating via a sophisticated system of flags, torches, and mounted messengers. They employed psychological warfare on a massive scale, deliberately spreading terrifying rumors of their brutality to encourage cities to surrender without a fight. When cities resisted, the consequences were apocalyptic: the population of the Khwarezmian Empire (modern Iran and Central Asia) may have dropped by 90% during the Mongol invasion. Entire cities were wiped from the map.\n\nBy the time of Genghis Khan\'s death in 1227, the Mongol Empire stretched from the Pacific Ocean to the Caspian Sea. Under his successors, it would expand further — into Russia, the Middle East, China, and Korea — becoming the largest contiguous land empire in history, covering 24 million square kilometers. But Genghis Khan\'s legacy was not only destruction. The Mongol Empire created the first true free-trade zone across Eurasia, protected by the "Pax Mongolica." Silk Road trade flourished as never before. Ideas, technologies, and diseases flowed freely between East and West. Gunpowder, paper money, the compass, and printing — Chinese inventions — began their journey toward Europe, while the bubonic plague traveled the same routes in the opposite direction.', year: 1206, eraId: 'medieval', latitude: 47.9184, longitude: 106.9177, category: 'political', locationName: 'Karakorum, Mongolia', imageUrl: 'https://images.unsplash.com/photo-1600751267958-5bb0d08beb41?w=640&q=80&fit=crop', impactText: 'A 2003 genetic study estimated that roughly 16 million men alive today — about 0.5% of the world\'s male population — are direct descendants of Genghis Khan, making him arguably the most reproductively successful individual in human history.', videoUrl: 'https://www.youtube.com/embed/wUVvTqvjUaM', modelUrl: 'https://sketchfab.com/models/f47196f7ebdb432c89b51af20d31a6e9/embed?autostart=1&ui_theme=dark' },
  { id: 'magna-carta', title: 'Magna Carta Signed', description: 'On June 15, 1215, in a meadow called Runnymede beside the River Thames, a group of rebellious English barons forced the most powerful monarch in Europe to his knees — figuratively, if not literally. King John, whose disastrous military campaigns had lost England\'s territories in France, whose crushing taxes had impoverished the nobility, and whose arbitrary imprisonments had made enemies of nearly every powerful family in the realm, affixed his royal seal to a document that would become the most celebrated charter of liberties in Western history: the Magna Carta, the "Great Charter."\n\nThe document itself was a practical, sometimes tedious list of 63 clauses addressing the specific grievances of 13th-century feudal lords — regulating inheritance taxes, standardizing weights and measures, limiting the king\'s ability to seize property or imprison people without legal process. Most of its provisions were obsolete within a generation. But buried within its Latin text were revolutionary principles that would echo across centuries: "No free man shall be seized, imprisoned, dispossessed, outlawed, or exiled, or in any way destroyed... except by the lawful judgment of his peers or by the law of the land." For the first time in English history, the idea was codified that even the king was subject to the law — that power had limits, and that those limits could be written down and enforced.\n\nKing John had no intention of honoring the charter. Within weeks, he appealed to Pope Innocent III, who annulled it, and England plunged into civil war. John died the following year, and his nine-year-old son Henry III reissued a revised Magna Carta to buy peace. Over the following centuries, the charter was reissued, revised, and reinterpreted dozens of times. By the 17th century, English lawyers and parliamentarians had elevated it into a foundational myth of constitutional liberty. Its influence flows directly into the English Bill of Rights of 1689, the American Declaration of Independence, the U.S. Constitution, and the Universal Declaration of Human Rights — making a feudal document drafted by medieval barons the unlikely ancestor of modern democracy.', year: 1215, eraId: 'medieval', latitude: 51.4444, longitude: -0.5632, category: 'political', locationName: 'Runnymede, England', imageUrl: 'https://images.unsplash.com/photo-1681515152442-5cd41622091b?w=640&q=80&fit=crop', impactText: 'Only four original copies of the 1215 Magna Carta survive today. In 2007, a 1297 copy sold at auction for $21.3 million, making it one of the most expensive documents ever sold — for a text that was technically annulled by the Pope just ten weeks after it was sealed.' },
  { id: 'mansa-musa', title: 'Mansa Musa\'s Pilgrimage', description: 'In 1324, a caravan of staggering proportions set out from the city of Niani in the heart of West Africa, bound for Mecca. At its head rode Mansa Musa, the ruler of the Mali Empire, the richest human being who has ever lived. His entourage stretched as far as the eye could see: 60,000 men including 12,000 personal servants, 500 slaves each carrying a 2.7-kilogram staff of pure gold, and 80 camels each loaded with 136 kilograms of gold dust. The total value of the gold Musa carried has been estimated at $400 billion in today\'s currency — a concentration of personal wealth that makes modern billionaires look modest by comparison.\n\nWhen the caravan reached Cairo, Musa\'s three-month stay caused an economic crisis that would last over a decade. He gave away gold with such breathtaking generosity — to officials, merchants, beggars, and anyone who crossed his path — that he single-handedly crashed the price of gold across North Africa and the Middle East. The Egyptian gold dinar lost 20-25% of its value, and the markets of Cairo did not fully recover for twelve years. It was the only time in recorded history that one individual directly controlled the price of gold across an entire continent. On his return journey, Musa actually had to borrow gold back from Egyptian merchants at extortionate interest rates — inadvertently creating one of history\'s first international lending arrangements.\n\nMansa Musa\'s pilgrimage announced the Mali Empire\'s existence to the wider world with an impact that reverberated for centuries. European mapmakers placed Mali prominently on their charts, and the 1375 Catalan Atlas depicts Musa sitting on a golden throne holding a gold nugget. But Musa was far more than a spectacle of wealth. Upon returning home, he brought back architects and scholars who transformed Timbuktu into one of the world\'s great centers of learning. The Sankore Madrasah housed a library of between 400,000 and 700,000 manuscripts, making it one of the largest collections of knowledge in the medieval world — a West African beacon of scholarship that European historians would ignore for centuries.', year: 1324, eraId: 'medieval', latitude: 16.7735, longitude: -3.0074, category: 'political', locationName: 'Timbuktu, Mali', imageUrl: 'https://images.unsplash.com/photo-1552931549-06dc73ec0d25?w=640&q=80&fit=crop', impactText: 'Adjusted for inflation, Mansa Musa\'s fortune is estimated at approximately $400 billion — making him the wealthiest person in all of human history. Jeff Bezos, Elon Musk, and every modern billionaire are modest by comparison.', videoUrl: 'https://www.youtube.com/embed/O3YJMaL55TM', modelUrl: 'https://sketchfab.com/models/cedd63bfa1e64779a950fd43b431a765/embed?autostart=1&ui_theme=dark' },
  { id: 'aztec-tenochtitlan', title: 'Founding of Tenochtitlan', description: 'According to Aztec legend, the Mexica people had wandered for generations through the deserts of central Mexico, guided by their patron god Huitzilopochtli, who promised them a homeland where they would find an eagle perched on a cactus devouring a serpent. Around 1325, on a marshy island in the middle of Lake Texcoco, they saw the prophesied sign and founded Tenochtitlan — the city that would become the capital of the most powerful empire in the Americas. That image of the eagle and serpent endures today as the central emblem on Mexico\'s national flag.\n\nWhat the Mexica built on that unpromising swamp was nothing short of astonishing. By the time Spanish conquistadors first glimpsed Tenochtitlan in November 1519, it was one of the largest cities on Earth — home to an estimated 200,000 to 300,000 people, roughly five times the size of contemporary London. The city was laid out on a precise grid pattern, connected to the mainland by three great causeways, and threaded with canals that served as streets. At its center stood the Templo Mayor, a double pyramid 60 meters tall dedicated to Huitzilopochtli and the rain god Tlaloc, where ritual sacrifices were performed on a scale that horrified the Spanish. Surrounding it were palaces, schools, markets, botanical gardens, and a zoo that housed jaguars, eagles, and exotic animals from across the empire.\n\nThe great market of Tlatelolco, Tenochtitlan\'s sister city, amazed the Spanish more than any battle. The conquistador Bernal Diaz del Castillo wrote that 60,000 people traded there daily, selling everything from gold and jade to chocolate and slaves, with judges overseeing transactions and standardized measures ensuring fair trade. The city\'s agricultural system was equally ingenious: chinampas, or "floating gardens," were artificial islands built on the lake bed from layers of vegetation, mud, and stakes, creating some of the most productive farmland in the pre-industrial world. When Hernan Cortes and his allies destroyed Tenochtitlan in 1521 after a brutal 80-day siege, they leveled one of the great marvels of human civilization. Mexico City was built directly on its ruins.', year: 1325, eraId: 'medieval', latitude: 19.4326, longitude: -99.1332, category: 'construction', locationName: 'Mexico City, Mexico', imageUrl: 'https://images.unsplash.com/photo-1647220498890-f2ea9c3933a2?w=640&q=80&fit=crop', impactText: 'When Cortes first entered Tenochtitlan, his soldiers compared it to the enchanted cities in their favorite romance novel, "Amadis de Gaula." Many wrote that they could not believe their eyes — they had never seen anything so magnificent, not even in Spain.', videoUrl: 'https://www.youtube.com/embed/_nS6MpVbB_g', modelUrl: 'https://sketchfab.com/models/dc821d302e1a4215aac1522f90a373f9/embed?autostart=1&ui_theme=dark' },
  { id: 'hundred-years-war', title: 'Hundred Years\' War Begins', description: 'In 1337, King Edward III of England formally claimed the throne of France, igniting a dynastic conflict that would rage — with interruptions — for 116 years and transform both nations beyond recognition. Edward had a legitimate, if contested, claim through his mother Isabella, daughter of the French king Philip IV. When the last direct Capetian king died without a male heir and the French chose Philip VI of Valois instead, Edward initially accepted the decision. But when Philip confiscated English territories in Aquitaine, Edward retaliated by asserting his right to the French crown, launching the longest military conflict in European history.\n\nThe war\'s early decades belonged to England. At the Battle of Crecy in 1346, English longbowmen — commoners armed with six-foot yew bows that could pierce armor at 200 meters — annihilated the flower of French chivalry, killing over 1,500 knights and proving that the age of mounted aristocratic warfare was ending. At Poitiers in 1356, the English captured the French king himself, Jean II, and ransomed him for 3 million gold ecus — a sum so enormous it crippled France\'s economy for a generation. The Black Death, which struck in the middle of the conflict, killed roughly a third of both nations\' populations but barely slowed the fighting.\n\nThe war\'s most extraordinary figure appeared at its darkest hour for France. In 1429, a 17-year-old peasant girl named Joan of Arc, claiming divine visions, convinced the desperate Dauphin Charles to give her command of an army. She lifted the siege of Orleans in just nine days and escorted Charles to his coronation at Reims Cathedral, turning the tide of the entire war. Captured by the Burgundians and sold to the English, she was burned at the stake in 1431 at age 19. But France\'s resurgence was unstoppable. By 1453, England had lost everything on the continent except Calais. The war forged modern national identities for both countries, ended feudal chivalric warfare, and established the professional standing army as the foundation of the nation-state.', year: 1337, eraId: 'medieval', latitude: 50.2734, longitude: 1.8787, category: 'war', locationName: 'Crecy, France', imageUrl: 'https://images.unsplash.com/photo-1460194436988-671f763436b7?w=640&q=80&fit=crop', impactText: 'The English longbow was so devastating that a trained archer could loose 12 arrows per minute at ranges exceeding 200 meters — a rate of fire not matched by firearms until the invention of the breech-loading rifle in the 19th century, over 500 years later.' , videoUrl: 'https://www.youtube.com/embed/rNCw2MOfnLQ' },
  { id: 'black-death', title: 'The Black Death', description: 'In October 1347, twelve Genoese trading ships docked at the port of Messina in Sicily. The sailors aboard were dying — covered in mysterious black swellings the size of eggs that oozed blood and pus, burning with fever, and delirious with pain. The harbor authorities ordered the ships out immediately, but it was already too late. The rats aboard the ships — and the fleas they carried, infected with the bacterium Yersinia pestis — had already come ashore. Within five years, the Black Death would kill between 75 and 200 million people across Eurasia, annihilating roughly 30-60% of Europe\'s entire population. It was the deadliest pandemic in human history.\n\nThe plague traveled along trade routes with terrifying speed. From Sicily, it swept through Italy, reaching Florence by the spring of 1348. The writer Giovanni Boccaccio, who survived, described bodies piled in the streets, families abandoning their sick, and entire neighborhoods left empty. "How many valiant men, how many fair ladies, breakfasted with their kinfolk and that same night supped with their ancestors in the next world!" The plague crossed the Alps, ravaged France and Spain, reached England by June 1348, and pushed into Scandinavia and Russia by 1351. Entire villages were wiped out. In some regions, there were not enough living to bury the dead.\n\nParadoxically, the Black Death may have been the catalyst that ended the Middle Ages. With labor suddenly scarce, surviving peasants could demand higher wages and better conditions — when lords refused, it sparked massive uprisings like the English Peasants\' Revolt of 1381. Serfdom began to crumble. The Church, which had been unable to explain or stop the plague, lost credibility, opening space for new intellectual movements. Some historians argue that the Renaissance itself was partly born from the social upheaval of the plague — a civilization forced to rebuild reimagined everything, from art to economics to the very relationship between humanity and God.', year: 1347, eraId: 'medieval', latitude: 43.7696, longitude: 11.2558, category: 'natural', locationName: 'Florence, Italy', imageUrl: 'https://images.unsplash.com/photo-1744584592746-d24062e3aab7?w=640&q=80&fit=crop', impactText: 'The Black Death was so devastating that it took Europe over 200 years to recover its pre-plague population level. England\'s population in 1300 was about 5-6 million; it did not reach that number again until the late 16th century.', videoUrl: 'https://www.youtube.com/embed/ySClB6-OH-Q', modelUrl: 'https://sketchfab.com/models/c5ef4feac1d6416bb70d6e21a289236e/embed?autostart=1&ui_theme=dark' },
  { id: 'zheng-he-voyages', title: 'Zheng He\'s Treasure Voyages', description: 'In 1405, the largest naval fleet the world had ever seen set sail from the port of Nanjing. Its commander was Zheng He, a Muslim eunuch who stood nearly two meters tall — an imposing figure who had risen from captured child slave to become the most trusted admiral of the Yongle Emperor. His flagship, the "Treasure Ship," was a floating colossus estimated at 120 meters long and 50 meters wide — nearly five times the length of Columbus\'s Santa Maria, which would not sail for another 87 years. The fleet comprised over 300 vessels carrying 27,000 men: sailors, soldiers, diplomats, translators, doctors, and merchants. Nothing remotely comparable would be seen on the world\'s oceans for centuries.\n\nOver seven voyages spanning 28 years, Zheng He\'s armada sailed throughout Southeast Asia, across the Indian Ocean to India, the Persian Gulf, the Red Sea, and down the east coast of Africa as far as Mozambique. These were not voyages of conquest but of diplomacy and trade on a scale that dwarfed anything Europe was capable of at the time. Zheng He distributed lavish gifts of silk, porcelain, and gold, collected tribute and exotic goods — including a giraffe that the Chinese court believed was a qilin, a mythical creature whose appearance signaled heavenly approval of the emperor\'s rule — and established Chinese diplomatic influence across the maritime world.\n\nThen, as abruptly as they began, the voyages stopped. After the Yongle Emperor\'s death, a new faction at court — Confucian scholars who viewed ocean trade as wasteful and corrupting — gained power. The treasure fleet was dismantled, the ships rotted at their moorings, and the logs of Zheng He\'s voyages were deliberately burned. China turned inward, ceding the world\'s oceans to European powers who would arrive in Asian waters within decades. Historians have debated ever since what might have happened if China had continued: with its naval superiority, advanced technology, and vast resources, the Age of Exploration might have been Chinese rather than European, and the entire trajectory of global history would have been different.', year: 1405, eraId: 'medieval', latitude: 32.0603, longitude: 118.7969, category: 'discovery', locationName: 'Nanjing, China', imageUrl: 'https://images.unsplash.com/photo-1748960844700-90cc77fab14c?w=640&q=80&fit=crop', impactText: 'Zheng He\'s treasure ships were so large that Columbus\'s Santa Maria could have fit inside one of their cargo holds. The fleet carried enough provisions for 27,000 men, including live animals and hydroponic gardens grown onboard for fresh vegetables.', modelUrl: 'https://sketchfab.com/models/9846a9e2af0a4e44a87bb5838670f77c/embed?autostart=1&ui_theme=dark' },
  { id: 'gutenberg-press', title: 'Gutenberg Printing Press', description: 'Around 1440, in a cramped workshop in Mainz, Germany, a goldsmith and inventor named Johannes Gutenberg was perfecting a technology that would change the world more profoundly than any invention since the wheel. His breakthrough was not printing itself — the Chinese had been printing with carved wooden blocks for centuries — but the development of movable metal type: individual letter molds cast from a durable lead-tin-antimony alloy that could be arranged, printed, disassembled, and reused endlessly. Combined with an adapted wine press and a new oil-based ink that adhered to metal, Gutenberg\'s system could produce pages of text with unprecedented speed and consistency.\n\nGutenberg\'s masterpiece was his 42-line Bible, completed around 1455 — a work of such extraordinary beauty that it could pass for a hand-copied manuscript. Each of the approximately 180 copies took about three years to produce, but this was revolutionary: a single scribe would need the same time to copy just one Bible by hand. Tragically, Gutenberg himself never profited from his invention. His financial backer, Johann Fust, sued him for repayment of loans, won, and seized the printing equipment. Gutenberg died in relative obscurity in 1468. But his technology spread like wildfire: by 1500, an estimated 1,000 printing shops across Europe had produced over 20 million volumes.\n\nThe printing press did not just make books cheaper — it democratized knowledge itself and destabilized every institution built on controlling information. Martin Luther\'s 95 Theses, printed and distributed across Germany in weeks, ignited the Protestant Reformation; without the press, it might have remained a local academic dispute. Scientific discoveries could be shared rapidly and accurately. Literacy rates soared. The press made possible the Renaissance, the Scientific Revolution, and the Enlightenment. Five centuries later, when the internet arrived, many commentators reached for the same comparison: "This is the biggest change since Gutenberg."', year: 1440, eraId: 'medieval', latitude: 49.9929, longitude: 8.2473, category: 'discovery', locationName: 'Mainz, Germany', imageUrl: 'https://images.unsplash.com/photo-1503694978374-8a2fa686963a?w=640&q=80&fit=crop', impactText: 'Only 49 copies of Gutenberg\'s original Bible survive today, and they are among the most valuable books on Earth. A complete copy sold at auction in 1987 for $5.4 million, and a single leaf (one page) can fetch over $100,000.', videoUrl: 'https://www.youtube.com/embed/EuzAbE-kPkM', modelUrl: 'https://sketchfab.com/models/dc159c5993e94136b5c9b20dc24addeb/embed?autostart=1&ui_theme=dark' },
  { id: 'machu-picchu', title: 'Machu Picchu Constructed', description: 'Perched on a narrow ridge 2,430 meters above sea level, between two Andean peaks and above the roaring Urubamba River, Machu Picchu is the most spectacular archaeological site in the Americas. Built around 1450 CE during the reign of the Inca emperor Pachacuti — the visionary ruler who transformed the Inca from a small highland kingdom into the largest empire in pre-Columbian America — the citadel was likely a royal retreat and sacred religious site for Inca elites. Its roughly 200 structures include temples, residences, fountains, and agricultural terraces, all constructed from precisely cut granite blocks fitted together without mortar so perfectly that a knife blade cannot be inserted between them.\n\nThe engineering required to build Machu Picchu on such a precarious site was extraordinary. The Inca had no iron tools, no wheeled vehicles, and no written language, yet they created a masterpiece of civil engineering. More than 60% of the construction is underground: a sophisticated drainage system of layered gravel, sand, and stone channels prevents the frequent tropical rains from destabilizing the hillside. The agricultural terraces were built with layers of topsoil hauled up from the river valley below, and an aqueduct system channeled water from a natural spring through 16 cascading fountains. The Intihuatana stone — a precisely carved granite pillar — functions as an astronomical clock that accurately indicates the winter and summer solstices.\n\nRemarkably, the Spanish conquistadors who destroyed so much of Inca civilization never found Machu Picchu. The site was abandoned sometime in the 16th century, possibly during the civil wars that followed the Spanish conquest, and the jungle gradually reclaimed it. It remained known only to local farmers until 1911, when American historian Hiram Bingham, guided by an 11-year-old local boy named Pablito Alvarez, stumbled upon the vine-covered ruins. The discovery electrified the world and revealed the sophistication of a civilization that European conquerors had dismissed as primitive — an empire that had built a city in the clouds.', year: 1450, eraId: 'medieval', latitude: -13.1631, longitude: -72.5450, category: 'construction', locationName: 'Cusco Region, Peru', imageUrl: 'https://images.unsplash.com/photo-1539017691474-d280be4d3290?w=640&q=80&fit=crop', impactText: 'The granite blocks of Machu Picchu are cut so precisely that they have survived 500 years of earthquakes without mortar. When tremors hit, the dry-stone walls "dance" — the blocks bounce and then fall back into place — an anti-seismic technique that modern engineers have studied.', modelUrl: 'https://sketchfab.com/models/d59370ac4a444628b95081f5bb7bbd02/embed?autostart=1&ui_theme=dark' },
  { id: 'fall-of-constantinople', title: 'Fall of Constantinople', description: 'On the morning of May 29, 1453, after a 53-day siege, the 21-year-old Ottoman Sultan Mehmed II — whom history would call "the Conqueror" — breached the legendary walls of Constantinople, ending the Byzantine Empire and 1,123 years of continuous Roman civilization. The city\'s Theodosian Walls, built in the 5th century and never before breached by a besieging army, finally met their match in Mehmed\'s secret weapon: a massive cannon forged by a Hungarian engineer named Orban, so enormous that it required 60 oxen to transport and fired stone balls weighing over 500 kilograms. The bombardment shattered the ancient walls, and when Ottoman troops poured through the gaps, the last Byzantine Emperor, Constantine XI Palaiologos, tore off his imperial regalia and charged into the fighting. His body was never positively identified.\n\nThe fall was a cataclysm that shook Christian Europe to its foundations. Constantinople had been the bulwark of Christendom against Islamic expansion for a millennium, and its loss sent shockwaves from Rome to London. Pope Nicholas V called for a new Crusade that never materialized. The Greek scholar Bessarion wrote to the Doge of Venice: "A city which was so flourishing... the refuge of all good things, has been captured, despoiled, ravaged, and completely sacked by the most inhuman barbarians." Thousands of Byzantine scholars fled westward, carrying with them priceless manuscripts of ancient Greek philosophy, science, and literature — an intellectual exodus that directly fueled the Italian Renaissance.\n\nMehmed immediately set about transforming Constantinople into Istanbul, the magnificent capital of the Ottoman Empire. He converted the Hagia Sophia into a mosque, repopulated the devastated city by bringing in settlers from across his domains, and rebuilt it as a cosmopolitan imperial capital that would rival any city in the world. The fall of Constantinople also had a profound economic consequence: the Ottoman control of overland trade routes to Asia intensified European efforts to find sea routes eastward — the search that would lead Columbus to the Americas and Vasco da Gama around Africa, launching the Age of Exploration that reshaped the globe.', year: 1453, eraId: 'medieval', latitude: 41.0082, longitude: 28.9784, category: 'war', locationName: 'Istanbul, Turkey', imageUrl: 'https://images.unsplash.com/photo-1763965367191-6455ef032c79?w=640&q=80&fit=crop', impactText: 'Sultan Mehmed II was so determined to bypass Constantinople\'s sea chain that he had 70 warships dragged overland on greased logs across a hill behind Galata — a distance of over a kilometer — to launch them into the Golden Horn harbor from the landward side, completely bypassing the city\'s naval defenses.', videoUrl: 'https://www.youtube.com/embed/8W0OTGQEY8E', modelUrl: 'https://sketchfab.com/models/7ace12b1517545eab8cc11549cb60c90/embed?autostart=1&ui_theme=dark' },
  { id: 'spanish-inquisition', title: 'Spanish Inquisition Established', description: 'On November 1, 1478, Pope Sixtus IV issued the papal bull "Exigit Sincerae Devotionis Affectus," granting King Ferdinand II and Queen Isabella I of Spain the authority to establish an inquisition under royal control — a decision that would unleash one of the most feared institutions in European history. The Spanish Inquisition was originally aimed at conversos — Jews who had converted to Christianity but were suspected of secretly practicing Judaism — but it quickly expanded its reach to include Muslims, Protestants, blasphemers, bigamists, and anyone whose beliefs deviated from Catholic orthodoxy. Its first Grand Inquisitor, the Dominican friar Tomas de Torquemada, became synonymous with religious persecution.\n\nThe Inquisition\'s methods were systematic and terrifying. Accusations could be anonymous. The accused were imprisoned, often for months, before being told the charges against them. Torture was authorized by papal decree and applied with bureaucratic precision — the rack, the water cure (an early form of waterboarding), and the strappado (suspension by bound wrists) were standard procedures, all meticulously documented by scribes. Those found guilty faced punishments ranging from public penance and confiscation of property to imprisonment and death by burning at the stake in elaborate public ceremonies called autos-da-fe — acts of faith — that drew thousands of spectators.\n\nThe Inquisition\'s broader impact was catastrophic for Spain. The expulsion of Jews in 1492 and of unconverted Muslims (Moriscos) between 1502 and 1614 drove out some of the most educated, skilled, and economically productive members of Spanish society. Merchants, physicians, scientists, and artisans who had flourished in Spain for centuries took their talents to the Ottoman Empire, the Netherlands, and the Americas. Many historians argue that the Inquisition contributed directly to Spain\'s long economic and intellectual decline. The institution survived for an astonishing 356 years, not being formally abolished until 1834 — making it one of the longest-lasting instruments of religious persecution in history.', year: 1478, eraId: 'medieval', latitude: 37.3886, longitude: -5.9823, category: 'political', locationName: 'Seville, Spain', imageUrl: 'https://images.unsplash.com/photo-1770507885733-310bed4094b4?w=640&q=80&fit=crop', impactText: 'Despite its fearsome reputation, the Spanish Inquisition actually executed fewer people than most assume — roughly 3,000 to 5,000 over 356 years. By comparison, secular courts across Europe executed far more people for witchcraft alone. The Inquisition\'s real power was psychological: the mere threat of investigation ruined lives, careers, and families.' , videoUrl: 'https://www.youtube.com/embed/zmcKS47BsAo' },
  { id: 'columbus-americas', title: 'Columbus Reaches the Americas', description: 'At 2 a.m. on October 12, 1492, a sailor named Rodrigo de Triana aboard the Pinta spotted a white sand cliff gleaming in the moonlight and cried out "Tierra! Tierra!" After 36 days crossing the open Atlantic — a voyage most European scholars believed was suicide — Christopher Columbus and his crew of roughly 90 men had reached a small island in the Bahamas that the indigenous Taino people called Guanahani. Columbus, convinced he had reached the outer islands of Asia, named it San Salvador and claimed it for the Spanish Crown. He was wrong about where he was by an entire hemisphere, but the consequences of his error would reshape every continent on Earth.\n\nColumbus\'s voyage was not an act of lone genius. The Portuguese had been methodically exploring the African coast for decades, and the idea of sailing west to reach Asia was circulating among European navigators. What Columbus had — beyond considerable seamanship — was relentless salesmanship and extraordinary luck. He dramatically underestimated the circumference of the Earth (the ancient Greeks had actually calculated it more accurately), and had the Americas not existed, his crew would have starved in the open Pacific. He made four voyages to the Caribbean between 1492 and 1504, dying in 1506 still believing he had reached Asia, never knowing he had stumbled upon two vast continents unknown to Europeans.\n\nThe collision of the Old and New Worlds that Columbus initiated was the most consequential event of the last millennium. The "Columbian Exchange" sent potatoes, tomatoes, corn, and tobacco eastward, and horses, wheat, cattle, and smallpox westward. European diseases, against which indigenous populations had no immunity, devastated the Americas — some estimates suggest 90% of the pre-contact population of the Western Hemisphere died within a century. Entire civilizations — the Taino, the Aztec, the Inca — were destroyed or subjugated. The wealth extracted from the Americas funded European empires and reshaped the global economy, while the forced transport of millions of enslaved Africans created a transatlantic horror whose consequences endure to this day.', year: 1492, eraId: 'renaissance', latitude: 24.0667, longitude: -74.5167, category: 'discovery', locationName: 'San Salvador, Bahamas', imageUrl: 'https://images.unsplash.com/photo-1487901155524-307f976ad775?w=640&q=80&fit=crop', impactText: 'Columbus\'s first voyage was funded for about 2 million maravedis (roughly $15,000 in today\'s money). The return on investment was incalculable: within 50 years, Spain was extracting more gold and silver from the Americas than existed in all of Europe combined.', videoUrl: 'https://www.youtube.com/embed/GD3dgiDreGc', modelUrl: 'https://sketchfab.com/models/b84f1cbd92b747f69db4f26a6f40a68c/embed?autostart=1&ui_theme=dark' },
  { id: 'reformation-luther', title: 'Martin Luther\'s 95 Theses', description: 'On October 31, 1517, a 33-year-old Augustinian monk and theology professor named Martin Luther reportedly nailed a document to the door of the Castle Church in Wittenberg, Germany — an act of academic protest that would shatter the religious unity of Western Christendom forever. The document, formally titled "Disputation on the Power and Efficacy of Indulgences," listed 95 propositions challenging the Catholic Church\'s sale of indulgences — certificates that promised to reduce a soul\'s time in purgatory in exchange for money. Luther\'s core argument was devastating in its simplicity: salvation came through faith alone, not through payments to the Church, and no pope or priest had the authority to broker deals with God.\n\nLuther had intended an academic debate, not a revolution. But the printing press — Gutenberg\'s invention, less than 80 years old — transformed his Latin theses into a viral phenomenon. Translated into German, printed in pamphlet form, and distributed across the Holy Roman Empire within weeks, Luther\'s arguments struck a nerve in a society already resentful of a Church that extracted enormous wealth from Germany while delivering it to Rome. When Pope Leo X demanded Luther recant and Luther publicly burned the papal decree in response, there was no turning back. At the Diet of Worms in 1521, standing before Emperor Charles V and the assembled princes of the Empire, Luther declared: "Here I stand; I can do no other."\n\nThe Reformation that Luther ignited tore Europe apart. Within a generation, half of Germany, all of Scandinavia, England, Scotland, the Netherlands, and parts of Switzerland had broken from Rome. The Catholic Church launched its Counter-Reformation at the Council of Trent. The resulting religious wars — the French Wars of Religion, the Thirty Years\' War, and the English Civil War — killed millions and redrew the map of Europe. But the Reformation also planted ideas that would reshape the modern world: the primacy of individual conscience over institutional authority, the importance of literacy (Luther insisted every Christian should read the Bible), and the radical notion that ordinary people could challenge the most powerful institutions on Earth and win.', year: 1517, eraId: 'renaissance', latitude: 51.8671, longitude: 12.6369, category: 'cultural', locationName: 'Wittenberg, Germany', imageUrl: 'https://images.unsplash.com/photo-1655135760727-a066179fef90?w=640&q=80&fit=crop', impactText: 'Luther\'s German translation of the Bible was so widely read that it essentially standardized the German language. Before Luther, Germany had dozens of mutually unintelligible dialects; his Bible gave them a common written tongue — making Luther arguably the father of modern German.' },
  { id: 'copernicus-heliocentric', title: 'Copernicus Publishes Heliocentric Model', description: 'In 1543, a 70-year-old Polish canon named Nicolaus Copernicus lay on his deathbed in the cathedral town of Frombork when a freshly printed copy of his life\'s work was placed in his hands. "De Revolutionibus Orbium Coelestium" — "On the Revolutions of the Celestial Spheres" — contained an idea so radical that Copernicus had delayed its publication for over 30 years out of fear: the Earth was not the center of the universe. Instead, the Earth and all the planets revolved around the Sun. This simple proposition overturned 1,400 years of Ptolemaic astronomy, challenged the literal interpretation of scripture, and set in motion the Scientific Revolution that would fundamentally transform humanity\'s understanding of its place in the cosmos.\n\nCopernicus was not the first to suggest heliocentrism — the ancient Greek astronomer Aristarchus of Samos had proposed it in the 3rd century BCE — but he was the first to back it with a comprehensive mathematical model. Working with primitive instruments in a tower overlooking the Baltic Sea, making painstaking observations over decades, Copernicus demonstrated that a sun-centered model explained the observed motions of the planets more elegantly than the Earth-centered Ptolemaic system, which had required an increasingly absurd tangle of epicycles (circles upon circles) to account for planetary retrograde motion. His system was not perfect — he still assumed circular orbits rather than elliptical ones — but its core insight was revolutionary.\n\nThe full impact of Copernicus\'s work took decades to unfold. The Catholic Church initially paid little attention; it was not until Galileo aggressively championed heliocentrism in the 1610s and 1620s that the Church banned "De Revolutionibus" in 1616. But Copernicus had opened a door that could not be closed. Tycho Brahe\'s precise observations, Johannes Kepler\'s discovery of elliptical orbits, and Galileo\'s telescopic revelations built upon his foundation, culminating in Isaac Newton\'s laws of gravity that unified terrestrial and celestial mechanics. The "Copernican Revolution" became the metaphor for any paradigm-shattering insight — the moment when humanity realized that appearances deceive, and that the universe does not revolve around us.', year: 1543, eraId: 'renaissance', latitude: 54.3558, longitude: 19.6830, category: 'discovery', locationName: 'Frombork, Poland', imageUrl: 'https://images.unsplash.com/photo-1744605745887-25e20b7d1652?w=640&q=80&fit=crop', impactText: 'Copernicus only saw the first printed copy of his masterwork on the day he died — May 24, 1543. Legend says he woke from a coma, gazed at the book, and then passed away. The Church did not ban the book until 73 years later, in 1616.', videoUrl: 'https://www.youtube.com/embed/w70BkCqgyyI', modelUrl: 'https://sketchfab.com/models/b57c5788aadb426784b30fc9b6d4cd0f/embed?autostart=1&ui_theme=dark' },
  { id: 'edo-period-japan', title: 'Tokugawa Shogunate Established', description: 'On March 24, 1603, Tokugawa Ieyasu — the patient, calculating warlord who had spent decades outmaneuvering his rivals — received the title of Shogun from the Japanese Emperor, formally establishing the Tokugawa Shogunate and ending over a century of devastating civil war known as the Sengoku period. Ieyasu\'s victory at the Battle of Sekigahara in 1600, where 160,000 warriors clashed in what was the largest samurai battle in history, had already decided Japan\'s fate. But his establishment of a government in the fishing village of Edo — modern-day Tokyo — would create a political system so stable it would endure for 265 years, governing one of the most remarkable periods of peace, cultural flowering, and isolation in world history.\n\nThe Tokugawa system was a masterpiece of political engineering designed to prevent any rival from ever again threatening the shogun\'s authority. The roughly 260 daimyo (feudal lords) were required to maintain residences in Edo and spend every other year at the shogun\'s court under the sankin-kotai system — essentially a hostage arrangement that kept potential rebels under surveillance while draining their resources on elaborate processions and dual households. The social hierarchy was frozen: samurai, farmers, artisans, merchants — each knew their place, and movement between classes was virtually forbidden. Most dramatically, starting in the 1630s, the Tokugawa enacted the sakoku (closed country) policy, expelling all foreigners except a tiny Dutch trading post on a man-made island in Nagasaki harbor, and forbidding Japanese from leaving the country on pain of death.\n\nYet within this rigid, isolated world, Japanese culture flourished spectacularly. Edo grew into one of the largest cities on Earth, with a population exceeding one million by 1720. The arts exploded: kabuki theater, ukiyo-e woodblock prints (whose bold compositions would later electrify the French Impressionists), haiku poetry perfected by Matsuo Basho, and the refined aesthetics of the tea ceremony all blossomed during this era. Literacy rates reached levels unmatched anywhere outside of northern Europe. When Commodore Matthew Perry\'s American warships forced Japan open in 1853, they encountered not a backward nation but a sophisticated, highly organized society that would modernize with astonishing speed — transforming from a feudal state into an industrial power in a single generation.', year: 1603, eraId: 'renaissance', latitude: 35.6762, longitude: 139.6503, category: 'political', locationName: 'Tokyo, Japan', imageUrl: 'https://images.unsplash.com/photo-1759041878359-120ca946dd75?w=640&q=80&fit=crop', impactText: 'Under the sankin-kotai system, the constant processions of daimyo traveling to and from Edo were so large — some included over 4,000 retainers — that they required an extensive network of roads, inns, and supply stations, accidentally creating Japan\'s first national transportation infrastructure.', videoUrl: 'https://www.youtube.com/embed/Nosq94oCl_M', modelUrl: 'https://sketchfab.com/models/0480d3d8b5fe4d9dbfdee854ce9f4bcf/embed?autostart=1&ui_theme=dark' },
  { id: 'galileo-telescope', title: 'Galileo\'s Telescopic Discoveries', description: 'In the autumn of 1609, a 45-year-old mathematics professor at the University of Padua pointed a homemade telescope at the night sky and saw things no human being had ever seen before. Galileo Galilei had not invented the telescope — that credit belongs to the Dutch spectacle maker Hans Lippershey — but Galileo was the first to turn it toward the heavens with the systematic eye of a scientist, and what he discovered in a few feverish months of observation overturned two millennia of astronomical assumptions. The Moon was not a perfect celestial sphere as Aristotle had taught; its surface was rough, cratered, and mountainous. The Milky Way was not a luminous cloud but a vast collection of individual stars too faint to see with the naked eye.\n\nGalileo\'s most explosive discovery came in January 1610, when he observed four tiny points of light orbiting Jupiter — the moons now called Io, Europa, Ganymede, and Callisto. This was devastating to the geocentric model of the universe. If moons could orbit Jupiter, the Earth was clearly not the center around which everything revolved. He published his findings in "Sidereus Nuncius" ("Starry Messenger") in March 1610, and the book made him the most famous scientist in Europe virtually overnight. He also observed that Venus showed phases like the Moon — possible only if Venus orbited the Sun, not the Earth — providing further evidence for the Copernican heliocentric model.\n\nGalileo\'s insistence on championing heliocentrism brought him into direct collision with the Catholic Church. In 1616, the Church declared heliocentrism "formally heretical," and in 1633, after publishing his provocative "Dialogue Concerning the Two Chief World Systems," Galileo was hauled before the Roman Inquisition, found "vehemently suspect of heresy," and sentenced to house arrest for the remainder of his life. Legend says he muttered "Eppur si muove" — "And yet it moves" — as he left the courtroom. Whether or not he actually said it, the words became the rallying cry of scientific truth against dogmatic authority. Galileo died under house arrest in 1642, the same year Isaac Newton was born.', year: 1609, eraId: 'renaissance', latitude: 45.4064, longitude: 11.8768, category: 'discovery', locationName: 'Padua, Italy', imageUrl: 'https://images.unsplash.com/photo-1600456548090-7d1b3f0bbea5?w=640&q=80&fit=crop', impactText: 'Galileo died in 1642 and Isaac Newton was born that same year — though under different calendars (Italy used the Gregorian, England the Julian). The Catholic Church did not formally admit it was wrong to condemn Galileo until 1992 — 359 years after the trial.', modelUrl: 'https://sketchfab.com/models/41e23659c75241459eec6477d9e77c93/embed?autostart=1&ui_theme=dark' },
  { id: 'manhattan-purchase', title: 'Purchase of Manhattan', description: 'In 1626, Peter Minuit, the newly arrived Director of the Dutch colony of New Netherland, conducted what is often called the most lopsided real estate deal in history: he purchased the island of Manhattan from the Lenape people for 60 guilders\' worth of trade goods — beads, cloth, metal tools, and other items. A 19th-century historian calculated this at $24, creating one of the most enduring legends in American folklore. But the reality is far more complicated than the myth. The Lenape likely viewed the transaction not as a permanent sale of land — a concept foreign to most Native American cultures — but as a temporary agreement to share the use of the territory. They had no idea they were signing away an island forever.\n\nThe Dutch settlement of New Amsterdam that grew on Manhattan\'s southern tip was unlike any other colonial outpost. From its founding, it was a polyglot trading hub where dozens of languages were spoken and tolerance was a business necessity. Dutch merchants, Walloon refugees, English dissenters, Sephardic Jews fleeing the Portuguese Inquisition in Brazil, free and enslaved Africans, and Lenape traders all mingled on the muddy streets around what is now Wall Street (named for an actual wooden wall the Dutch built as a northern defensive barrier). The settlement\'s commercial DNA — trade above all, profit as the organizing principle — would define the city\'s character for the next four centuries.\n\nIn 1664, the English seized New Amsterdam without a fight and renamed it New York. The island that Peter Minuit had purchased for the equivalent of a few boxes of supplies would become the financial capital of the world. Today, the total real estate value of Manhattan alone exceeds $1.7 trillion. The 59-square-kilometer island is home to Wall Street, the United Nations, Times Square, and Central Park — a concentration of economic, cultural, and political power unmatched by any comparable patch of ground on Earth.', year: 1626, eraId: 'renaissance', latitude: 40.7128, longitude: -74.0060, category: 'political', locationName: 'Manhattan, New York', imageUrl: 'https://images.unsplash.com/photo-1609945648638-cefddce6e6d8?w=640&q=80&fit=crop', impactText: 'If the 60 guilders Peter Minuit paid for Manhattan in 1626 had been invested at 6.5% compound interest, it would be worth over $2 trillion today — roughly equal to Manhattan\'s actual current real estate value, making it a surprisingly fair deal by the math.', modelUrl: 'https://sketchfab.com/models/a34eebc7966c4589934afb2334e182b6/embed?autostart=1&ui_theme=dark' },
  { id: 'taj-mahal', title: 'Taj Mahal Construction Begins', description: 'In 1632, the Mughal Emperor Shah Jahan, devastated by the death of his beloved wife Mumtaz Mahal during the birth of their fourteenth child, commissioned a mausoleum so beautiful it would make the world weep. The result — the Taj Mahal — is widely regarded as the most beautiful building ever constructed, a monument to love that took 22 years, 20,000 workers, and 1,000 elephants to complete. Rising from the banks of the Yamuna River in Agra, its luminous white marble dome and four flanking minarets have become the most recognized architectural silhouette on Earth, a building so perfectly proportioned that it appears to float above its reflecting pool like a vision from paradise.\n\nThe Taj Mahal\'s beauty lies not only in its form but in its extraordinary attention to detail. The white Makrana marble was quarried 300 kilometers away in Rajasthan and transported by a fleet of 1,000 elephants. Into this marble, craftsmen inlaid 28 varieties of precious and semi-precious stones — jasper from Punjab, jade from China, turquoise from Tibet, lapis lazuli from Afghanistan, sapphires from Sri Lanka, and carnelian from Arabia — using the pietra dura technique, creating intricate floral patterns so fine that a single 3-centimeter flower contains 60 individual stone inlays. The calligraphy adorning the entrance arches, rendered in black marble, reproduces entire chapters of the Quran, with the letters subtly increasing in size as they ascend so they appear uniform when viewed from below.\n\nThe building is also an optical masterpiece. The four minarets are tilted very slightly outward, so that if they ever collapsed, they would fall away from the central tomb rather than onto it. The dome changes color throughout the day — pinkish in the morning, white at noon, golden in the moonlight — because the translucent marble responds differently to every angle of light. Shah Jahan, deposed by his own son Aurangzeb in 1658, spent his final eight years imprisoned in Agra Fort, gazing across the river at the tomb of the woman he had loved. He was buried beside Mumtaz Mahal, the only element of the Taj Mahal that breaks its otherwise perfect symmetry — a poignant final detail that makes the building\'s love story feel unfinished even after four centuries.', year: 1632, eraId: 'renaissance', latitude: 27.1751, longitude: 78.0421, category: 'construction', locationName: 'Agra, India', imageUrl: 'https://images.unsplash.com/photo-1577125305658-dee71d4ee3c7?w=640&q=80&fit=crop', impactText: 'Legend holds that Shah Jahan planned to build an identical black marble Taj Mahal across the river for his own tomb, connected to the original by a bridge. While most historians consider this a myth, archaeological surveys have found traces of foundations on the opposite bank.', videoUrl: 'https://www.youtube.com/embed/v580zy82rcE', modelUrl: 'https://sketchfab.com/models/f5f69f1d7e764eecb2dafd948d6b9fde/embed?autostart=1&ui_theme=dark' },
  { id: 'french-revolution', title: 'French Revolution', description: 'On the morning of July 14, 1789, a Parisian mob — hungry, furious, and armed with muskets looted from the Hotel des Invalides — surged toward the Bastille, a medieval fortress-prison in the heart of Paris that had become the hated symbol of royal tyranny. The garrison of 82 invalides (retired soldiers) and 32 Swiss guards held out for hours, but by afternoon the outer courtyard was breached. The governor, the Marquis de Launay, surrendered and was dragged into the street, where the crowd stabbed him to death and paraded his head on a pike. Only seven prisoners were found inside, but that hardly mattered. The storming of the Bastille was the thunderclap that announced the death of the old order.\n\nThe Revolution had been building for decades. France was bankrupt — largely from funding the American Revolution, ironically — and its tax system was grotesquely unfair: the nobility and clergy paid almost nothing while the common people were crushed. A series of bad harvests had driven bread prices to record highs; by 1789, a laborer spent roughly 88% of his wages just on bread. When King Louis XVI summoned the Estates-General for the first time in 175 years to address the fiscal crisis, the representatives of the common people (the Third Estate) broke away to form the National Assembly, vowing not to disband until France had a constitution. The king\'s attempt to shut them down by force ignited the explosion.\n\nWhat followed was a decade of upheaval that remade not just France but the entire Western world. The Declaration of the Rights of Man and of the Citizen established that sovereignty belonged to the nation, not the king. The monarchy was abolished, Louis XVI and Marie Antoinette were guillotined, and the Revolution devoured its own children during the Terror, when Robespierre sent thousands to the blade before he himself was executed. Out of the chaos rose Napoleon Bonaparte, who would spread revolutionary ideals — and French armies — across all of Europe. The Revolution\'s principles of liberty, equality, and popular sovereignty became the template for virtually every democratic movement that followed, from the Haitian Revolution to the Arab Spring.', year: 1789, eraId: 'renaissance', latitude: 48.8532, longitude: 2.3692, category: 'political', locationName: 'Paris, France', imageUrl: 'https://images.unsplash.com/photo-1663615311146-5a2307cd6e60?w=640&q=80&fit=crop', impactText: 'During the Reign of Terror, the guillotine was so busy that residents near the Place de la Revolution complained about the smell of blood. An estimated 16,594 people were officially sentenced to death, but the true toll including extrajudicial killings may have exceeded 40,000.', videoUrl: 'https://www.youtube.com/embed/8qRZcXIODNU', modelUrl: 'https://sketchfab.com/models/4fd48175b15b4047a2deba77ca22d44a/embed?autostart=1&ui_theme=dark' },
  { id: 'steam-locomotive', title: 'First Steam Locomotive', description: 'On February 21, 1804, in the industrial town of Merthyr Tydfil in south Wales, a Cornish engineer named Richard Trevithick made a bet that would change the world. He wagered 500 guineas that his new steam-powered locomotive could haul 10 tons of iron along the Penydarren tramway, a 15-kilometer route connecting an ironworks to the Merthyr-Cardiff canal. The ungainly machine — belching steam, clanking and groaning — completed the journey in just over four hours, carrying not only the iron but also 70 curious men who had climbed aboard for the ride. It was the first time in history that a steam locomotive had successfully hauled a load on rails.\n\nTrevithick\'s locomotive was ahead of its time — literally. The cast-iron tramway plates, designed for horse-drawn wagons, kept cracking under the engine\'s 5-ton weight, and the Penydarren locomotive was eventually converted into a stationary engine. Trevithick himself, a brilliant but commercially hapless inventor, never profited from his breakthrough and died penniless in 1833. It would take another two decades for George Stephenson to solve the practical problems and launch the first public steam railway — the Stockton and Darlington Railway in 1825, followed by the epochal Liverpool and Manchester Railway in 1830.\n\nBut Trevithick\'s proof of concept in that Welsh valley was the spark that ignited the Railway Age. Within 50 years, over 30,000 kilometers of railroad track crisscrossed Britain, and the technology had spread to every continent. Railways didn\'t just move goods faster — they restructured human civilization. They created standard time zones (before railways, every town set its own clocks). They enabled the growth of suburbs, national markets, and mass tourism. They made possible the rapid mobilization of armies that defined modern warfare. The Industrial Revolution was powered by coal and steam, but it moved on rails — and it all began with a bet on a Welsh hillside.', year: 1804, eraId: 'industrial', latitude: 51.7507, longitude: -3.3791, category: 'discovery', locationName: 'Merthyr Tydfil, Wales', imageUrl: 'https://images.unsplash.com/photo-1544129564-b07b639606bb?w=640&q=80&fit=crop', impactText: 'Before railways, every town in Britain kept its own local time based on the sun. A town just 15 kilometers west could be several minutes behind. Railways made this chaos dangerous, so in 1847 the Railway Clearing House imposed "Railway Time" — the origin of standardized time zones used worldwide today.', modelUrl: 'https://sketchfab.com/models/f254aaf8c490497993ded11c4f0955a2/embed?autostart=1&ui_theme=dark' },
  { id: 'suez-canal', title: 'Suez Canal Opens', description: 'On November 17, 1869, a flotilla of ships led by the French imperial yacht L\'Aigle, carrying Empress Eugenie of France, sailed into a canal that should not have existed. The Suez Canal — 164 kilometers of waterway cut through the Egyptian desert connecting the Mediterranean Sea to the Red Sea — had been dismissed as an impossible fantasy by most engineers, including the British, who actively tried to sabotage the project. But Ferdinand de Lesseps, a French diplomat with no engineering background but limitless charisma and connections, had spent 15 years turning the dream into reality. The opening ceremony was the most extravagant party of the 19th century, with 6,000 guests, a new opera house in Cairo (Verdi\'s Aida was commissioned for the occasion, though it premiered late), and fireworks that lit up the desert sky.\n\nThe construction had been brutal. Work began in 1859 with corvee labor — essentially forced Egyptian peasants, up to 20,000 at a time, digging with picks and baskets in the scorching heat. Thousands died from cholera, dysentery, and exhaustion. When international pressure ended the corvee system in 1863, de Lesseps pivoted to steam-powered dredges and excavators that ultimately moved 74 million cubic meters of earth. The project cost over double its initial estimate and nearly bankrupted Egypt — the Khedive was eventually forced to sell his shares in the canal to the British government for 4 million pounds, a bargain that gave Britain de facto control of the waterway for nearly a century.\n\nThe canal\'s impact on global trade was immediate and revolutionary. The voyage from London to Bombay, previously a 19,800-kilometer journey around the Cape of Good Hope taking four to six months, was cut nearly in half. World shipping patterns were redrawn overnight. Control of the canal became a geopolitical obsession — Britain stationed troops there for decades, and the Suez Crisis of 1956, when Egypt nationalized the canal, became one of the defining moments of the Cold War. Today, roughly 12% of all global trade passes through this narrow strip of water, and a single ship blocking the canal in 2021 (the Ever Given incident) cost the global economy an estimated $9.6 billion per day.', year: 1869, eraId: 'industrial', latitude: 30.4574, longitude: 32.3499, category: 'construction', locationName: 'Suez, Egypt', imageUrl: 'https://images.unsplash.com/photo-1587634552378-199c247a85c5?w=640&q=80&fit=crop', impactText: 'The idea of a canal at Suez is ancient — Pharaoh Necho II began digging one around 600 BCE, and a version connecting the Nile to the Red Sea functioned intermittently for over a thousand years. Napoleon surveyed the route in 1798 but abandoned the idea after his engineers incorrectly calculated a 10-meter difference in sea levels between the Mediterranean and the Red Sea.', videoUrl: 'https://www.youtube.com/embed/i9p-a8YJO-o', modelUrl: 'https://sketchfab.com/models/4a66ca23ba7640ae87e7a0117897d9c7/embed?autostart=1&ui_theme=dark' },
  { id: 'eiffel-tower', title: 'Eiffel Tower Completed', description: 'When Gustave Eiffel proposed a 300-meter iron tower for the 1889 World\'s Fair — commemorating the centennial of the French Revolution — the Parisian cultural establishment erupted in outrage. A petition signed by 300 prominent artists and intellectuals, including Guy de Maupassant, Alexandre Dumas fils, and Charles Garnier (architect of the Paris Opera), denounced the project as "a gigantic black smokestack" and "a hateful column of bolted sheet metal" that would disfigure the Paris skyline. Maupassant himself reportedly ate lunch at the tower\'s restaurant every day — because it was the only place in Paris from which he couldn\'t see the tower.\n\nThe construction was a masterpiece of industrial engineering. Over two years, 300 workers assembled 18,038 pieces of puddled iron (a type of wrought iron), connected by 2.5 million rivets, using detailed blueprints that specified the position of every single rivet hole. Despite working at dizzying heights — the tower rose to 300 meters, nearly twice the height of any existing structure — not a single worker was killed during construction (one death occurred during the installation of the elevators after the structure was completed). The four gracefully curving legs, which critics had mocked as ugly, were actually calculated using sophisticated wind-resistance equations; the tower\'s shape is essentially a mathematical curve that minimizes wind stress, a principle now fundamental to structural engineering.\n\nThe Eiffel Tower was meant to be temporary — its permit was for 20 years, after which it would be dismantled. It was saved by its usefulness as a radio transmission antenna; in 1910, it transmitted the first radio time signal broadcast across the globe, and during World War I, it intercepted enemy wireless communications that helped turn the tide of the Battle of the Marne. Today, the tower that Paris once despised is its most beloved icon, attracting nearly 7 million visitors annually and serving as the most-visited paid monument in the world. It has been repainted 19 times in its history, requiring 60 tons of paint each time.', year: 1889, eraId: 'industrial', latitude: 48.8584, longitude: 2.2945, category: 'construction', locationName: 'Paris, France', imageUrl: 'https://images.unsplash.com/photo-1502602898657-3e91760cbb34?w=640&q=80&fit=crop', impactText: 'The Eiffel Tower grows and shrinks with the seasons: thermal expansion of the iron causes it to be up to 15 centimeters taller in summer heat than in winter cold, and it leans slightly away from the sun as the heated side expands.', modelUrl: 'https://sketchfab.com/models/a68b9ffb898d4aa7a44505926a536ce3/embed?autostart=1&ui_theme=dark' },
  { id: 'ww1', title: 'World War I Begins', description: 'On June 28, 1914, a 19-year-old Bosnian Serb named Gavrilo Princip stepped forward on a Sarajevo street corner and fired two shots from a Browning pistol into the open car carrying Archduke Franz Ferdinand, heir to the Austro-Hungarian throne, and his wife Sophie. Both died within the hour. It was a local act of political violence in a provincial city — but it triggered a cascade of ultimatums, mobilizations, and alliance obligations that, within six weeks, had plunged all of Europe into the most devastating war the world had ever seen. By the time the guns fell silent on November 11, 1918, over 17 million people were dead, four empires had collapsed, and the world that existed before the war was gone forever.\n\nThe war that everyone expected to be "over by Christmas" instead became a four-year nightmare of industrial slaughter. On the Western Front, opposing armies dug into a continuous line of trenches stretching 700 kilometers from the Swiss border to the English Channel, and for years neither side could break through. The Battle of the Somme in 1916 cost over one million casualties for a territorial gain of barely 10 kilometers. New technologies — machine guns, poison gas, tanks, aircraft, and submarines — made killing efficient on an unprecedented scale while leaving the strategic stalemate unbroken. Soldiers lived in mud-filled trenches infested with rats, surrounded by the unburied dead, enduring constant shelling that produced a new psychological condition: shell shock.\n\nThe war\'s consequences were seismic. The Austro-Hungarian, Ottoman, Russian, and German empires all disintegrated. The map of Europe and the Middle East was redrawn, creating new nations — Czechoslovakia, Yugoslavia, Iraq, Syria — whose borders, drawn by diplomats with little regard for ethnic or cultural realities, would generate conflicts that persist to this day. The punitive Treaty of Versailles humiliated Germany and sowed the seeds of an even more terrible war just two decades later. The generation that survived the trenches was forever changed; their disillusionment fueled the modernist movements in art, literature, and philosophy that defined the 20th century.', year: 1914, eraId: 'modern', latitude: 48.2082, longitude: 16.3738, category: 'war', locationName: 'Vienna, Austria', imageUrl: 'https://images.unsplash.com/photo-1572966901946-e5c9ac18c283?w=640&q=80&fit=crop', impactText: 'On Christmas Day 1914, soldiers along parts of the Western Front spontaneously declared an unofficial truce. German and British troops climbed out of their trenches, exchanged gifts, sang carols together, and even played football in no man\'s land — before returning to killing each other the next day.', videoUrl: 'https://www.youtube.com/embed/dHSQAEam2yc', modelUrl: 'https://sketchfab.com/models/a8846676166f43b8a4e8d0e8c3be41a8/embed?autostart=1&ui_theme=dark' },
  { id: 'ww2', title: 'World War II Begins', description: 'At 4:45 a.m. on September 1, 1939, without a declaration of war, the German battleship Schleswig-Holstein opened fire on the Polish military garrison at Westerplatte, and 1.5 million Wehrmacht soldiers poured across the Polish border in a coordinated assault by land and air. The Blitzkrieg — "lightning war" — combined fast-moving tanks, motorized infantry, and dive-bombing Stuka aircraft in a new form of warfare that shattered the Polish army in weeks. Warsaw, subjected to relentless aerial bombardment that killed tens of thousands of civilians, surrendered on September 27. Two days later, Britain and France, bound by treaty to defend Poland, declared war on Germany. The deadliest conflict in human history had begun.\n\nOver the next six years, the war engulfed every inhabited continent. Nazi Germany conquered most of Europe and launched the Holocaust — the systematic, industrialized murder of six million Jews and millions of others in death camps that represented humanity\'s darkest chapter. Japan\'s empire swept across East Asia and the Pacific. The Soviet Union, after losing 27 million people — more than any other nation — turned the tide at Stalingrad in the bloodiest battle ever fought. The war saw the development of radar, jet engines, ballistic missiles, and nuclear weapons. It ended with the atomic bombings of Hiroshima and Nagasaki in August 1945, which killed over 200,000 people and ushered in the nuclear age.\n\nThe scale of World War II defies comprehension. An estimated 70-85 million people perished — roughly 3% of the world\'s entire population. Cities from London to Tokyo were reduced to rubble. The political map was redrawn: the European colonial empires began their collapse, the United States and Soviet Union emerged as rival superpowers, and the Cold War began. The United Nations was founded to prevent such a catastrophe from recurring. The Nuremberg Trials established that "following orders" was no defense for war crimes — a legal principle that shapes international law to this day. The world that emerged from the ashes of 1945 was fundamentally different from the one that had existed in 1939.', year: 1939, eraId: 'modern', latitude: 52.2297, longitude: 21.0122, category: 'war', locationName: 'Warsaw, Poland', imageUrl: 'https://images.unsplash.com/photo-1685299102134-d054445b0215?w=640&q=80&fit=crop', impactText: 'The Soviet Union lost an estimated 27 million people in World War II — roughly 14% of its entire population. To put this in perspective, it means that for every single day of the war, an average of over 14,000 Soviet citizens died.', videoUrl: 'https://www.youtube.com/embed/_uk_6vfqwTA', modelUrl: 'https://sketchfab.com/models/a3763aefecda48fc9b4084dc2d625f5e/embed?autostart=1&ui_theme=dark' },
  { id: 'moon-landing', title: 'Moon Landing', description: 'At 10:56 p.m. EDT on July 20, 1969, Neil Armstrong placed his left foot on the powdery gray surface of the Moon and spoke the most famous words of the 20th century: "That\'s one small step for man, one giant leap for mankind." An estimated 600 million people — one-fifth of the world\'s population — watched the grainy black-and-white television broadcast, holding their breath as a human being walked on another world for the first time in history. Nineteen minutes later, Buzz Aldrin joined him, and together they spent two and a half hours on the lunar surface, collecting 21.5 kilograms of moon rocks, planting an American flag, and conducting experiments — while Michael Collins orbited alone overhead in the command module, the loneliest human being in existence, cut off from all radio contact every time he passed behind the Moon.\n\nThe journey to this moment had been a decade-long sprint fueled by Cold War rivalry and national pride. In 1961, President John F. Kennedy had committed the United States to landing a man on the Moon before the end of the decade — at a time when America\'s total human spaceflight experience amounted to 15 minutes. NASA\'s budget swelled to nearly 4.5% of the federal budget (compared to less than 0.5% today), and at its peak the Apollo program employed over 400,000 people across 20,000 companies. The technical challenges were immense: three astronauts died in a launch pad fire during Apollo 1, and the program came within seconds of catastrophe multiple times.\n\nThe lunar module Eagle landed with less than 25 seconds of fuel remaining — Armstrong had been forced to take manual control and fly past the intended landing site when he saw it was strewn with boulders. The onboard guidance computer, which had less processing power than a modern pocket calculator and just 72 kilobytes of memory, threw multiple alarms during the descent that nearly aborted the landing. Between 1969 and 1972, twelve humans walked on the Moon across six Apollo missions. Then, abruptly, the program ended. No human has returned to the lunar surface since Apollo 17 in December 1972 — making the Moon landings, paradoxically, both humanity\'s greatest technological achievement and a capability we chose to abandon.', year: 1969, eraId: 'modern', latitude: 28.5721, longitude: -80.6480, category: 'discovery', locationName: 'Cape Canaveral, Florida', imageUrl: 'https://images.unsplash.com/photo-1614726365930-627c75da663e?w=640&q=80&fit=crop', impactText: 'The Apollo 11 astronauts had to go through U.S. Customs when they returned to Earth. Their customs declaration form listed their cargo as "moon rock and moon dust samples" and their departure point as "the Moon." They were also quarantined for 21 days in case they had brought back alien pathogens.', videoUrl: 'https://www.youtube.com/embed/QhULJr-LKbg', modelUrl: 'https://sketchfab.com/models/372bb6781922471cada4e0a9bd5c61fb/embed?autostart=1&ui_theme=dark' },
  { id: 'berlin-wall', title: 'Fall of the Berlin Wall', description: 'On the evening of November 9, 1989, an East German government spokesman named Gunter Schabowski held a press conference to announce new, slightly relaxed travel regulations. When a journalist asked when the new rules took effect, Schabowski shuffled through his papers, found no specific date, and shrugged: "Immediately, without delay." He had made a mistake — the regulations were supposed to take effect the next day, with orderly processing. But the news spread instantly. Within hours, tens of thousands of East Berliners surged toward the wall\'s checkpoints, demanding to cross. The overwhelmed border guards, receiving no clear orders from their superiors, opened the gates. The Berlin Wall — the most infamous symbol of the Cold War — had fallen, not through military force or political negotiation, but through a bureaucratic blunder at a press conference.\n\nThe Wall had divided Berlin for 28 years. Built almost overnight on August 13, 1961, by the East German government to stop the hemorrhage of citizens fleeing to the West, it was not one wall but two, separated by a "death strip" of raked sand (to show footprints), guard towers, anti-vehicle trenches, and tripwire-activated automatic guns. At least 140 people were killed trying to cross it, some shot in full view of West Berlin residents. The Wall became the physical manifestation of the Iron Curtain — the dividing line between communist East and capitalist West that had defined global politics since 1945.\n\nWhen the gates opened that November night, the scenes were extraordinary. Strangers embraced in tears. People danced on top of the Wall, something that would have gotten them shot 24 hours earlier. Champagne flowed freely. "Mauerspechte" (wall woodpeckers) arrived with hammers and chisels to chip off souvenir fragments. Within a year, Germany was officially reunified. Within two years, the Soviet Union itself had dissolved. The Cold War — which had threatened nuclear annihilation for four decades, fueled proxy wars across the globe, and divided families, cities, and entire nations — was over. An era that had defined the second half of the 20th century ended with a party, not a war.', year: 1989, eraId: 'modern', latitude: 52.5163, longitude: 13.3777, category: 'political', locationName: 'Berlin, Germany', imageUrl: 'https://images.unsplash.com/photo-1636632082360-99ce6562731e?w=640&q=80&fit=crop', impactText: 'The fall of the Berlin Wall happened by accident. Spokesman Gunter Schabowski was handed the new travel regulations minutes before the press conference without being properly briefed. His off-the-cuff answer — "immediately, without delay" — was never authorized, but once broadcast live on television, it could not be taken back.', videoUrl: 'https://www.youtube.com/embed/A9fQPzZ1-hg', modelUrl: 'https://sketchfab.com/models/ebc5f582188c4f6b89bdde9b549cd96f/embed?autostart=1&ui_theme=dark' },
  { id: 'www-invention', title: 'World Wide Web Invented', description: 'In March 1989, a 33-year-old British computer scientist named Tim Berners-Lee submitted a proposal to his bosses at CERN, the European particle physics laboratory in Geneva, Switzerland. The document, titled "Information Management: A Proposal," outlined a system for linking documents across different computers using hypertext — clickable connections that could jump from one piece of information to another regardless of where it was stored. His supervisor\'s handwritten note on the cover page read simply: "Vague but exciting." It was perhaps the greatest understatement in the history of technology. Berners-Lee was proposing the World Wide Web.\n\nOver the next two years, Berners-Lee built the foundational technologies that make the web possible: HTML (the language for creating web pages), HTTP (the protocol for transmitting them), and URLs (the addressing system for finding them). He wrote the first web browser and the first web server, both running on a NeXT computer in his office at CERN. The first website — info.cern.ch — went live on December 20, 1990. A handwritten note taped to the computer read: "This machine is a server. DO NOT POWER IT DOWN!!" The web was initially used only by physicists sharing research papers, and it grew slowly at first: by 1993, there were only about 600 websites in the world.\n\nThen came the inflection point. In 1993, CERN made the extraordinary decision to release the web\'s source code into the public domain, making it free for anyone to use and build upon. Berners-Lee himself insisted on this — he could have patented the technology and become one of the wealthiest people in history, but he believed the web\'s power depended on its universality. The effect was explosive. By 1995, there were 23,000 websites; by 2000, over 17 million. Today, there are nearly 2 billion websites, and over 5 billion people — more than 60% of humanity — use the internet. The web has transformed commerce, communication, politics, entertainment, science, and human relationships more profoundly than any invention since the printing press, and it all started with a "vague but exciting" memo at a physics lab.', year: 1989, eraId: 'modern', latitude: 46.2044, longitude: 6.1432, category: 'discovery', locationName: 'Geneva, Switzerland', imageUrl: 'https://images.unsplash.com/photo-1571845413709-ba4ddc85eb12?w=640&q=80&fit=crop', impactText: 'The original NeXT computer that Tim Berners-Lee used as the first web server is now displayed at CERN with its original label still attached: "This machine is a server. DO NOT POWER IT DOWN!!" It is arguably the most important single computer in history.', videoUrl: 'https://www.youtube.com/embed/J8hzJxb0rpc' },
  { id: 'indus-valley', title: 'Indus Valley Civilization', description: 'Around 2600 BCE, the city of Mohenjo-daro in the Indus River floodplains housed 40,000 people with streets laid out in a precise grid pattern and a sophisticated underground drainage system. Every house had its own bathroom and toilet — a level of urban sanitation London would not achieve until the 1860s.\n\nThe Harappan civilization stretched across 1.25 million square kilometers, encompassing parts of modern Pakistan, India, and Afghanistan. At its peak it included over 1,000 settlements and perhaps five million people. Their standardized baked bricks maintained a precise 4:2:1 ratio across the entire civilization, and they were likely the first people to cultivate and weave cotton.\n\nThe civilization\'s greatest mystery is its undeciphered writing system — roughly 400 distinct symbols found on thousands of seals. Around 1900 BCE, shifting monsoon patterns dried up the rivers sustaining their agriculture, and the great cities were abandoned, not rediscovered until 1922.', year: -2600, endYear: -1900, eraId: 'ancient', latitude: 27.329, longitude: 68.138, category: 'construction', locationName: 'Mohenjo-daro, Pakistan', imageUrl: 'https://images.unsplash.com/photo-1608717310359-3a1e90a53504?w=640&q=80&fit=crop', impactText: 'Mohenjo-daro had flush toilets and citywide sewage in 2600 BCE — a level of sanitation London would not achieve until the 1860s, over 4,400 years later.', modelUrl: 'https://sketchfab.com/models/ea4f061f0a4e4d08b67ac1926877347c/embed?autostart=1&ui_theme=dark' },
  { id: 'shang-oracle-bones', title: 'Shang Dynasty Oracle Bones', description: 'Around 1200 BCE, royal diviners at Anyang inscribed questions onto turtle shells and ox bones, applied heated bronze rods until the bones cracked, and read the crack patterns as answers from ancestral spirits. These "oracle bones" lay buried for over three thousand years.\n\nIn 1899, a scholar named Wang Yirong noticed that "dragon bones" sold in a pharmacy bore an archaic form of Chinese writing. Excavations at Anyang unearthed over 150,000 fragments bearing approximately 4,500 distinct characters — the direct ancestor of modern Chinese characters, the longest continuously used writing system in human history.\n\nThe inscriptions record astronomical observations including eclipses, military campaigns of up to 13,000 soldiers, and specific king names that confirmed ancient dynastic records scholars had dismissed as mythology.', year: -1200, eraId: 'ancient', latitude: 36.12, longitude: 114.35, category: 'discovery', locationName: 'Anyang, China', imageUrl: 'https://images.unsplash.com/photo-1673628992008-8ff4be9f0544?w=640&q=80&fit=crop', impactText: 'For centuries before their significance was recognized, oracle bones were ground into powder and sold as "dragon bones" in Chinese pharmacies as a remedy for malaria. Countless priceless inscriptions were unknowingly swallowed as medicine.', modelUrl: 'https://sketchfab.com/models/96f9ae59a49b4a70a0c9b961602efcab/embed?autostart=1&ui_theme=dark' },
  { id: 'phoenician-alphabet', title: 'Phoenician Alphabet', description: 'Around 1050 BCE, Phoenician merchants in Byblos perfected a writing system of just 22 symbols, each representing a single consonant sound. Previous writing systems required years of study and thousands of symbols. The Phoenician alphabet could be learned in weeks, making literacy accessible beyond specialized scribes for the first time.\n\nFrom their city-states of Tyre, Sidon, and Byblos, the Phoenicians built a trading network spanning the Mediterranean. Their alphabet traveled with their commerce, carried on cargo manifests and letters in every port.\n\nThe Greeks adopted it around 800 BCE, adding vowels — alpha, beta, gamma are direct adaptations of aleph, beth, gimel. Greek begat Latin, which begat the script you are reading now. By some estimates, every alphabet-based writing system in the world traces back to those 22 Phoenician symbols.', year: -1050, eraId: 'ancient', latitude: 34.123, longitude: 35.651, category: 'discovery', locationName: 'Byblos, Lebanon', imageUrl: 'https://images.unsplash.com/photo-1772368871875-1f536b85ad75?w=640&q=80&fit=crop', impactText: 'The word "alphabet" comes from the first two Phoenician letters — aleph (ox) and beth (house). Even "Bible" derives from "Byblos," the city that was the ancient world\'s greatest papyrus exporter.' },
  { id: 'kingdom-of-kush', title: 'Kingdom of Kush Conquers Egypt', description: 'Around 750 BCE, King Piye of Kush rode north from Napata in modern Sudan and conquered Egypt — establishing the Twenty-Fifth Dynasty. Piye was no barbarian invader but a devout worshipper of Amun who wept upon discovering his enemies had mistreated their horses.\n\nUnder pharaoh Taharqa, the Kushite-Egyptian realm stretched from the Nile confluence to the Mediterranean. Taharqa built monuments at Karnak, fought the Assyrian superpower, and was mentioned in the Bible.\n\nAfter being driven from Egypt, the Kushites built over 200 pyramids at Meroe — more than Egypt itself. They developed their own partially deciphered writing system and smelted iron while Rome was still a village. Their story challenges the myth that sub-Saharan Africa produced no great civilizations.', year: -750, eraId: 'ancient', latitude: 16.938, longitude: 33.748, category: 'political', locationName: 'Meroe, Sudan', imageUrl: 'https://images.unsplash.com/photo-1764685761993-4bbb0cf4ba49?w=640&q=80&fit=crop', impactText: 'Sudan has more pyramids than Egypt — over 200 Kushite pyramids survive in northern Sudan compared to Egypt\'s roughly 130, yet they remain almost entirely unknown to tourists.', modelUrl: 'https://sketchfab.com/models/b395c56bdeec4047853670c7cd39ef72/embed?autostart=1&ui_theme=dark' },
  { id: 'persian-empire-cyrus', title: 'Persian Empire Founded by Cyrus', description: 'In 550 BCE, Cyrus II launched a rebellion against the Median Empire and won, then conquered Lydia and Babylon within eleven years, creating the Achaemenid Empire — the largest the world had yet seen, eventually encompassing 44% of the world\'s population.\n\nWhen Cyrus entered Babylon in 539 BCE, instead of sacking the city he freed captive peoples including the Jews, earning the only non-Jewish "messiah" title in the Hebrew Bible. The Cyrus Cylinder records his policy of religious tolerance — called the world\'s first charter of human rights.\n\nHis empire connected territories through the 2,700-kilometer Royal Road with relay stations that could carry a message from Susa to Sardis in seven days. Cyrus died in battle in 530 BCE; his tomb at Pasargadae still stands.', year: -550, eraId: 'classical', latitude: 30.062, longitude: 53.167, category: 'political', locationName: 'Pasargadae, Iran', imageUrl: 'https://images.unsplash.com/photo-1562576605-88930bca8574?w=640&q=80&fit=crop', impactText: 'A replica of the Cyrus Cylinder is displayed at the United Nations headquarters in New York — Iran considers it a foundational document of Persian identity.', modelUrl: 'https://sketchfab.com/models/09ec072aaa974c31a0d486e60dc18196/embed?autostart=1&ui_theme=dark' },
  { id: 'birth-of-buddhism', title: 'Birth of Buddhism', description: 'Around 500 BCE, Prince Siddhartha Gautama abandoned his palace to seek the answer to human suffering. After years of extreme asceticism, he sat beneath a pipal tree in Bodh Gaya and achieved enlightenment, becoming the Buddha — "the Awakened One."\n\nHe taught the Four Noble Truths and the Eightfold Path to anyone who would listen — kings and outcasts alike, rejecting the rigid caste system. He died around 483 BCE at age 80.\n\nWithin three centuries, Emperor Ashoka sent Buddhist missionaries across Asia. Buddhism reached China, Korea, Japan, and Tibet, becoming one of the world\'s great religions with over 500 million followers today.', year: -500, eraId: 'classical', latitude: 27.483, longitude: 83.276, category: 'cultural', locationName: 'Lumbini, Nepal', imageUrl: 'https://images.unsplash.com/photo-1553285207-a28928d5cc82?w=640&q=80&fit=crop', impactText: 'The Jaya Sri Maha Bodhi tree in Sri Lanka, grown from a cutting of the original Bodhi Tree, is the oldest verified human-planted tree in the world at over 2,300 years old.', modelUrl: 'https://sketchfab.com/models/229b2f23987c4fe48643a622c5bea542/embed?autostart=1&ui_theme=dark' },
  { id: 'battle-of-marathon', title: 'Battle of Marathon', description: 'In September 490 BCE, 10,000 Athenian hoplites faced 25,000 Persian soldiers at Marathon. General Miltiades weakened his center, strengthened both wings, and ordered a charge at a run — minimizing time under arrow fire. The gamble worked: the wings crushed the Persian flanks and enveloped the center. 6,400 Persians died compared to 192 Athenians.\n\nMarathon was the moment Western civilization almost died in its cradle. Had Athens fallen, its experiment with democracy would have been extinguished before Socrates, Plato, or the Parthenon.\n\nThe legend of Pheidippides running 42 km to Athens to announce victory inspired the modern marathon race. The odd 42.195 km distance was set at the 1908 London Olympics.', year: -490, eraId: 'classical', latitude: 38.114, longitude: 23.973, category: 'war', locationName: 'Marathon, Greece', imageUrl: 'https://images.unsplash.com/photo-1710864499705-81514e93c828?w=640&q=80&fit=crop', impactText: 'The modern marathon distance of 42.195 km was set at the 1908 London Olympics so the race could finish in front of the royal box — the actual Marathon-to-Athens distance is only about 40 km.', modelUrl: 'https://sketchfab.com/models/41ee688fc7ee4ea5ad4a984927ede2a2/embed?autostart=1&ui_theme=dark' },
  { id: 'parthenon-construction', title: 'Construction of the Parthenon', description: 'In 447 BCE, Pericles launched the most ambitious Greek building project: a temple to Athena atop the Acropolis. The Parthenon contains almost no straight lines — columns lean inward, the platform curves upward by 6 cm, and columns swell slightly in the middle to counteract optical illusions.\n\nOver 22,000 tons of marble were quarried and fitted without mortar, held by iron dowels and the precision of the contact surfaces. Inside stood a 12-meter statue of Athena covered in 1,100 kg of removable gold.\n\nThe Parthenon served as a Greek temple, Christian church, and Ottoman mosque. In 1687, a Venetian mortar shell hit it while it was being used as a gunpowder magazine, blowing out the center.', year: -447, eraId: 'classical', latitude: 37.971, longitude: 23.726, category: 'construction', locationName: 'Athens, Greece', imageUrl: 'https://images.unsplash.com/photo-1577543599916-551c9c4c1ca8?w=640&q=80&fit=crop', impactText: 'There is not a single straight line in the Parthenon. If the corner columns were extended upward, they would meet at a point roughly 2.4 km above the building.', modelUrl: 'https://sketchfab.com/models/d5cc54ccd57a4bdeb3c164a96c677b59/embed?autostart=1&ui_theme=dark' },
  { id: 'construction-of-petra', title: 'Construction of Petra', description: 'Around 300 BCE, the Nabataean people began carving a city directly into rose-red sandstone cliffs, accessible only through a narrow kilometer-long gorge called the Siq. Al-Khazneh ("The Treasury") stands 40 meters tall, sculpted from the top down from living rock.\n\nThe Nabataeans controlled the lucrative incense trade and built an elaborate system of dams, cisterns, and ceramic pipes that supported lush gardens in one of the driest landscapes on Earth.\n\nForgotten by the Western world for over 600 years, Petra was rediscovered in 1812 by Swiss explorer Johann Ludwig Burckhardt, disguised as an Arab pilgrim. Today it is a UNESCO World Heritage Site and one of the New Seven Wonders.', year: -300, eraId: 'classical', latitude: 30.328, longitude: 35.444, category: 'construction', locationName: 'Petra, Jordan', imageUrl: 'https://images.unsplash.com/photo-1551171129-8ce1ebb911b3?w=640&q=80&fit=crop', impactText: 'Only about 20% of Petra has been excavated. Archaeologists estimate that 80% of the ancient city remains underground, including potentially significant undiscovered buildings.', modelUrl: 'https://sketchfab.com/models/966b88f5768d43ed9ebf4cc726c42f3d/embed?autostart=1&ui_theme=dark' },
  { id: 'library-of-alexandria', title: 'Library of Alexandria Founded', description: 'Around 295 BCE, Ptolemy I founded an institution in Alexandria that may have held 400,000 to 700,000 scrolls — the accumulated intellectual output of the ancient world. Scholars there calculated Earth\'s circumference to within 2%, proposed heliocentrism, and wrote the most influential mathematics textbook ever created.\n\nThe library\'s acquisition policy was ruthless: every ship entering the harbor was searched for scrolls, which were confiscated, copied, and sometimes only the copies returned.\n\nThere was no single catastrophic fire. The library declined gradually through political neglect, reduced funding, and multiple incidents of damage over centuries. What was lost is incalculable — entire works of Sophocles, Euripides, and Aristotle vanished forever.', year: -295, eraId: 'classical', latitude: 31.200, longitude: 29.918, category: 'cultural', locationName: 'Alexandria, Egypt', imageUrl: 'https://images.unsplash.com/photo-1465929639680-64ee080eb3ed?w=640&q=80&fit=crop', impactText: 'Eratosthenes, the Library\'s third head librarian, calculated Earth\'s circumference to within 2% accuracy in 240 BCE using only two sticks, their shadows, and the distance between two cities.', modelUrl: 'https://sketchfab.com/models/1cc6ad6af508422398f60f902cb70e88/embed?autostart=1&ui_theme=dark' },
  { id: 'maurya-ashoka', title: 'Ashoka and the Maurya Empire', description: 'In 260 BCE, Emperor Ashoka conquered Kalinga, killing over 100,000 soldiers. Surveying the devastation, he was overcome with remorse and embraced Buddhism, devoting his remaining decades to non-violence, religious tolerance, and the welfare of all living beings.\n\nHe banned animal sacrifice, established the first known veterinary clinics, planted shade trees along roads, and carved his ethical principles on rock pillars across the subcontinent — one of the earliest examples of a ruler publicly committing to ethical governance.\n\nAshoka\'s lion capital from one of his pillars is today the national emblem of India, and the 24-spoked Dharma wheel from his edicts occupies the center of the Indian flag.', year: -260, eraId: 'classical', latitude: 25.620, longitude: 85.140, category: 'political', locationName: 'Pataliputra, India', imageUrl: 'https://images.unsplash.com/photo-1585744945554-5df801d2b680?w=640&q=80&fit=crop', impactText: 'A brutal conqueror turned pacifist became the founding symbol of the world\'s largest democracy — Ashoka\'s lion capital is India\'s national emblem and his Dharma wheel is on the flag.', modelUrl: 'https://sketchfab.com/models/a8347d4f5272439bb2396ea40551cfc9/embed?autostart=1&ui_theme=dark' },
  { id: 'rosetta-stone', title: 'Rosetta Stone Decree', description: 'In 196 BCE, Egyptian priests issued a decree in three scripts: hieroglyphic, Demotic, and Greek. French soldiers discovered the stone in 1799 near Rashid. The British seized it as war spoils and shipped it to the British Museum, where it remains.\n\nThe race to decipher it became one of the great intellectual contests of the 19th century. Jean-Francois Champollion cracked the code on September 14, 1822, reportedly shouting "I\'ve got it!" before collapsing unconscious from excitement.\n\nHis decipherment opened a door sealed for 1,400 years — suddenly every inscription on every temple, tomb, and papyrus in Egypt could be read, and an entire mute civilization began to speak again.', year: -196, eraId: 'classical', latitude: 31.396, longitude: 30.417, category: 'cultural', locationName: 'Rashid, Egypt', imageUrl: 'https://images.unsplash.com/photo-1692986172397-ef662fba9152?w=640&q=80&fit=crop', impactText: 'The last known hieroglyphic inscription was carved in 394 CE. Before Champollion\'s breakthrough in 1822, no living person on Earth could read a single hieroglyph — 1,400 years of silence.', modelUrl: 'https://sketchfab.com/models/1e03509704a3490e99a173e53b93e282/embed?autostart=1&ui_theme=dark' },
  { id: 'silk-road', title: 'Silk Road Established', description: 'Around 130 BCE, diplomat Zhang Qian returned to China after 13 years — captured twice, escaping twice — with intelligence about wealthy civilizations to the west. Emperor Wu secured the routes he mapped, and within decades a 6,400 km trade network connected China to Rome.\n\nThe routes carried silk, spices, glassware, and precious stones. Buddhist monks traveled eastward, transforming Chinese culture. Grapes, walnuts, and sesame were introduced to China while peaches, apricots, and cast iron moved westward.\n\nOasis cities like Samarkand and Bukhara became cosmopolitan hubs. The Silk Road was the nervous system of the Old World for over 1,500 years — until ocean-going ships made overland trade obsolete.', year: -130, eraId: 'classical', latitude: 34.265, longitude: 108.954, category: 'discovery', locationName: 'Xi\'an, China', imageUrl: 'https://images.unsplash.com/photo-1760681554227-d7aad73cd57f?w=640&q=80&fit=crop', impactText: 'Zhang Qian was held captive for 10 years but married a local woman and had a son before escaping. He is so revered in China that he is known as the "Great Traveler."', modelUrl: 'https://sketchfab.com/models/9e46a2caf8ad4a05ab375006756f09da/embed?autostart=1&ui_theme=dark' },
  { id: 'teotihuacan-founded', title: 'Teotihuacan Founded', description: 'Around 100 BCE, construction began on what would become the largest city in the pre-Columbian Americas. At its peak around 450 CE, Teotihuacan housed up to 200,000 people — larger than any European city of the era. The Pyramid of the Sun rises 65 meters with a base nearly as large as the Great Pyramid of Giza.\n\nThe entire city was laid out on a grid oriented 15.5 degrees east of true north — possibly aligned to the Pleiades star cluster. Residential compounds had interior courtyards, drainage systems, and vibrant polychrome murals.\n\nThe greatest mystery: we do not know who built it, what language they spoke, or what they called their city. "Teotihuacan" is Aztec for "the place where the gods were born."', year: -100, eraId: 'classical', latitude: 19.692, longitude: -98.843, category: 'construction', locationName: 'Teotihuacan, Mexico', imageUrl: 'https://images.unsplash.com/photo-1586933613001-b003c20beac0?w=640&q=80&fit=crop', impactText: 'The Aztecs discovered the ruins 700 years after the city\'s collapse and assumed only gods could have built something so massive — hence the name "the place where the gods were born."', modelUrl: 'https://sketchfab.com/models/1191545483b04a82bbe63475c666b0e8/embed?autostart=1&ui_theme=dark' },
  { id: 'pompeii-destroyed', title: 'Destruction of Pompeii', description: 'On August 24, 79 CE, Mount Vesuvius erupted, burying the city of Pompeii under 4-6 meters of ash. Roughly 2,000 of the city\'s 11,000 residents were killed — many frozen in the positions they died in by pyroclastic surges reaching 300°C and 700 km/h.\n\nSealed in its volcanic tomb for 1,600 years, Pompeii was perfectly preserved. Bread was still in ovens. Political graffiti covered walls. Erotic frescoes decorated a brothel. The plaster casts of victims are among the most haunting images in archaeology.\n\nPompeii taught us more about everyday Roman life than any other site — what people ate, how they decorated homes, what jokes they wrote on bathroom walls. Pliny the Younger\'s eyewitness account remains the earliest detailed description of a volcanic eruption.', year: 79, eraId: 'classical', latitude: 40.748, longitude: 14.484, category: 'natural', locationName: 'Pompeii, Italy', imageUrl: 'https://images.unsplash.com/photo-1746288856403-ee2ccee5ea61?w=640&q=80&fit=crop', impactText: 'Over 11,000 graffiti have been catalogued at Pompeii, including love declarations, political ads, insults, and even an ancient restaurant review: "The food here is poison."', modelUrl: 'https://sketchfab.com/models/1738c376769b4fa3bc402fb64a19564a/embed?autostart=1&ui_theme=dark' },
  { id: 'emancipation-proclamation', title: 'Emancipation Proclamation', description: 'On January 1, 1863, President Lincoln signed an executive order declaring all enslaved people in the Confederate states "henceforward shall be free." It was a radical act of wartime authority — Lincoln justified it as military necessity since enslaved labor sustained the Confederate war effort.\n\nNearly 180,000 Black men enlisted in the Union Army, providing a decisive manpower advantage. The Proclamation made it politically impossible for Britain and France to recognize the Confederacy.\n\nLincoln pressed for the Thirteenth Amendment to abolish slavery permanently. He was assassinated in April 1865, months before its ratification. The Proclamation freed approximately 3.5 million people from bondage.', year: 1863, eraId: 'industrial', latitude: 38.897, longitude: -77.036, category: 'political', locationName: 'Washington, D.C., USA', imageUrl: 'https://images.unsplash.com/photo-1726314685078-ac94d7dacfcf?w=640&q=80&fit=crop', impactText: 'Lincoln kept the Proclamation secret for months, waiting for a Union victory so it would not look like desperation. The Battle of Antietam — the bloodiest day in American history with 22,717 casualties — gave him the opening.', modelUrl: 'https://sketchfab.com/models/a888a9926abb4691a0b91d4eee24b61e/embed?autostart=1&ui_theme=dark' },
  { id: 'origin-of-species', title: 'Darwin Publishes Origin of Species', description: 'On November 24, 1859, Charles Darwin published a theory that shattered humanity\'s understanding of its place in nature. "On the Origin of Species" proposed that all living things evolved from common ancestors through natural selection. The first printing of 1,250 copies sold out on the day of publication.\n\nDarwin had sat on his theory for twenty years, terrified of the reaction, until Alfred Russel Wallace independently arrived at the same idea. The backlash was fierce — but within a generation the scientific community embraced evolution.\n\nToday the theory of evolution is the unifying framework of all modern biology. Darwin is buried in Westminster Abbey, just feet from Isaac Newton.', year: 1859, eraId: 'industrial', latitude: 51.507, longitude: -0.127, category: 'discovery', locationName: 'London, England', imageUrl: 'https://images.unsplash.com/photo-1559041881-74dd9fd9b600?w=640&q=80&fit=crop', impactText: 'The Linnean Society\'s reaction to the Darwin-Wallace paper in 1858 was spectacularly underwhelming. The president wrote that the year "has not been marked by any of those striking discoveries which at once revolutionize" science.', modelUrl: 'https://sketchfab.com/models/cc2c44858dce4bd782ce29d2e4832014/embed?autostart=1&ui_theme=dark' },
  { id: 'meiji-restoration', title: 'Meiji Restoration', description: 'On January 3, 1868, young samurai seized the imperial palace in Kyoto and abolished the 265-year-old Tokugawa shogunate, declaring a "restoration" of imperial rule. It was the most radical revolution in Japanese history — transforming a feudal society into an industrial world power in a single generation.\n\nThe Meiji government sent delegations to study everything from Prussian military organization to British naval engineering. They built railways, abolished the feudal class system, and established compulsory education.\n\nWithin thirty years, Japan defeated China. Within forty, it stunned the world by defeating Russia — the first modern victory of an Asian nation over a Western power. No other country has modernized so rapidly.', year: 1868, eraId: 'industrial', latitude: 35.676, longitude: 139.650, category: 'political', locationName: 'Tokyo, Japan', imageUrl: 'https://images.unsplash.com/photo-1663867385065-75540d5e2b71?w=640&q=80&fit=crop', impactText: 'The Meiji government hired over 3,000 foreign experts at enormous salaries — some earned more than the Prime Minister — to teach Western technology. Once Japanese learned the skills, the foreigners were sent home.', modelUrl: 'https://sketchfab.com/models/5aa01d75729949dcaa040e8fbbb74430/embed?autostart=1&ui_theme=dark' },
  { id: 'telephone-invention', title: 'Invention of the Telephone', description: 'On March 10, 1876, Alexander Graham Bell spilled acid on his trousers and shouted "Mr. Watson, come here — I want to see you." Watson heard the words through a wire — the first intelligible sentence transmitted by telephone. Bell had filed his patent just hours before rival Elisha Gray.\n\nBell\'s patent — U.S. Patent No. 174,465 — has been called the most valuable patent ever issued. He demonstrated the telephone at the 1876 Philadelphia Exhibition, where Brazil\'s Emperor exclaimed "My God, it talks!"\n\nBy 1900 there were over a million phones worldwide. Bell himself, ironically, refused to have a telephone in his study, finding it intrusive.', year: 1876, eraId: 'industrial', latitude: 42.360, longitude: -71.058, category: 'discovery', locationName: 'Boston, USA', imageUrl: 'https://images.unsplash.com/photo-1557180295-76eee20ae8aa?w=640&q=80&fit=crop', impactText: 'Bell\'s mother and wife were both deaf, which drove his lifelong work on sound and speech. He considered the telephone a distraction from his true passion — teaching the deaf.', modelUrl: 'https://sketchfab.com/models/c91467735c6743af872e65107a79beda/embed?autostart=1&ui_theme=dark' },
  { id: 'light-bulb', title: 'Edison\'s Practical Light Bulb', description: 'On October 21, 1879, Edison\'s team watched a carbonized cotton filament glow for over 13 hours. By November it lasted 100 hours; by 1880, a bamboo filament burned for 1,200 hours. The practical electric light bulb had arrived.\n\nEdison\'s true genius was the entire electrical infrastructure — generators, wiring, meters, fuses. On September 4, 1882, the Pearl Street Station in Manhattan lit 400 lamps in 85 buildings — the world\'s first commercial power station.\n\nFor 300,000 years of human history, nightfall meant darkness. Electric light extended the productive day, enabled modern surgery, nighttime entertainment, and factory night shifts. Edison\'s Menlo Park lab also pioneered the concept of industrial R&D.', year: 1879, eraId: 'industrial', latitude: 40.567, longitude: -74.331, category: 'discovery', locationName: 'Menlo Park, USA', imageUrl: 'https://images.unsplash.com/photo-1773441603910-304542a91ffd?w=640&q=80&fit=crop', impactText: 'Edison tested over 3,000 materials for filaments, including coconut hair and a friend\'s red beard hair. He allegedly said: "I have not failed. I\'ve just found 10,000 ways that won\'t work."', modelUrl: 'https://sketchfab.com/models/aeb0e4832f04463280510e550e2cdbd5/embed?autostart=1&ui_theme=dark' },
  { id: 'panama-canal', title: 'Panama Canal Opens', description: 'On August 15, 1914, the SS Ancon became the first vessel to transit the 77-kilometer Panama Canal. An estimated 25,000 workers had died during construction — one of the deadliest projects in history.\n\nThe French tried first, starting in 1881. Tropical diseases killed 20,000 workers. The company went bankrupt in France\'s largest financial scandal. The Americans succeeded by waging war on mosquitoes and abandoning the sea-level design for locks.\n\nToday approximately 14,000 ships pass through annually, carrying 5% of world trade. A $5.25 billion expansion completed in 2016 doubled the canal\'s capacity.', year: 1914, eraId: 'modern', latitude: 9.082, longitude: -79.519, category: 'construction', locationName: 'Panama City, Panama', imageUrl: 'https://images.unsplash.com/photo-1650900426337-0f7c0e0f86ea?w=640&q=80&fit=crop', impactText: 'The French failure triggered one of history\'s greatest financial scandals — the collapse ruined 800,000 investors and nearly brought down the French government.', modelUrl: 'https://sketchfab.com/models/4c11a0fd38ca42b4a066b11d71a8b50b/embed?autostart=1&ui_theme=dark' },
  { id: 'russian-revolution', title: 'Russian Revolution', description: 'On October 25, 1917, a blank shot from the cruiser Aurora signaled the Bolshevik assault on the Winter Palace. Most "attackers" simply walked through unlocked doors. But the consequences were world-shaking — Lenin\'s party seized power promising "Peace, Land, and Bread."\n\nA brutal civil war killed 7-12 million people. The Tsar and his family were executed. Lenin established a one-party state that endured for 74 years.\n\nThe Soviet Union inspired communist revolutions from China to Cuba and triggered the Cold War. The revolution proved that a determined minority could seize a vast nation and remake it according to ideology.', year: 1917, eraId: 'modern', latitude: 59.934, longitude: 30.335, category: 'political', locationName: 'St. Petersburg, Russia', imageUrl: 'https://images.unsplash.com/photo-1749971496152-f82b5372c730?w=640&q=80&fit=crop', impactText: 'The Germans secretly funded Lenin\'s return to Russia, hoping to destabilize it. The gamble worked — Russia left WWI — but the revolution Germany helped unleash would haunt Europe for the rest of the century.' },
  { id: 'penicillin-discovery', title: 'Discovery of Penicillin', description: 'In September 1928, Alexander Fleming returned from holiday to find a mold had contaminated a petri dish of bacteria — and the bacteria surrounding the mold had dissolved. "That\'s funny," he reportedly muttered, in perhaps the most consequential understatement in medical history.\n\nThe breakthrough languished for a decade until Howard Florey and Ernst Chain at Oxford purified it. By D-Day 1944, there was enough penicillin to treat every wounded Allied soldier.\n\nPenicillin has saved an estimated 200 million lives since its introduction. In his Nobel lecture, Fleming presciently warned about antibiotic resistance — a prediction that has become one of the most urgent health crises of the 21st century.', year: 1928, eraId: 'modern', latitude: 51.517, longitude: -0.174, category: 'discovery', locationName: 'London, England', imageUrl: 'https://images.unsplash.com/photo-1535127022272-dbe7ee35cf33?w=640&q=80&fit=crop', impactText: 'Fleming\'s discovery was pure accident — the mold spore likely blew in from a mycology lab one floor below. If Fleming had been tidier or closed his window, the discovery might have been delayed by decades.', modelUrl: 'https://sketchfab.com/models/4a65766980dc43e5b93705571bc04ec3/embed?autostart=1&ui_theme=dark' },
  { id: 'indian-independence', title: 'Indian Independence', description: 'At midnight on August 15, 1947, Nehru delivered one of the century\'s most stirring speeches: "At the stroke of the midnight hour, when the world sleeps, India will awake to life and freedom." After 200 years of British rule, the subcontinent was free — but partition into India and Pakistan triggered the largest mass migration in history.\n\nAn estimated 12-15 million people were displaced. Between 200,000 and two million were killed in sectarian violence. Gandhi, heartbroken, fasted in Calcutta to stop the killing. He was assassinated in January 1948.\n\nIndia adopted a democratic constitution in 1950 guaranteeing universal suffrage. Today it is the world\'s most populous country and largest democracy.', year: 1947, eraId: 'modern', latitude: 28.613, longitude: 77.209, category: 'political', locationName: 'New Delhi, India', imageUrl: 'https://images.unsplash.com/photo-1587474260584-136574528ed5?w=640&q=80&fit=crop', impactText: 'The India-Pakistan border was drawn by Sir Cyril Radcliffe, who had never been to India before. He was given just five weeks to divide 400 million people.' },
  { id: 'chinese-revolution', title: 'Chinese Communist Revolution', description: 'On October 1, 1949, Mao Zedong proclaimed the People\'s Republic of China from Tiananmen: "The Chinese people have stood up!" After a century of humiliation and 22 years of civil war, China had a new government.\n\nMao\'s revolution transformed China at staggering scale and cost. Land reform redistributed property but killed an estimated 1-2 million. The Great Leap Forward caused the worst famine in history, killing 15-55 million. The Cultural Revolution destroyed countless cultural artifacts.\n\nYet the revolution unified China, improved literacy, and laid foundations for the economic transformation that lifted 800 million from poverty.', year: 1949, eraId: 'modern', latitude: 39.904, longitude: 116.407, category: 'political', locationName: 'Beijing, China', imageUrl: 'https://images.unsplash.com/photo-1586784444981-ac96e335555c?w=640&q=80&fit=crop', impactText: 'The "loss of China" became a political weapon in America — Senator McCarthy used it to launch anti-communist witch hunts, asking "Who lost China?" as though a nation of 540 million had been America\'s to lose.' },
  { id: 'dna-structure', title: 'Discovery of DNA Structure', description: 'On February 28, 1953, Francis Crick burst into the Eagle pub in Cambridge and announced: "We have found the secret of life." That morning, he and James Watson had completed the double helix model of DNA. Their Nature paper was just 900 words long — one of the shortest and most consequential ever written.\n\nRosalind Franklin\'s "Photo 51" X-ray image was the critical clue — shown to Watson without her knowledge. She died of cancer at 37, never knowing her work had been shared. The Nobel Prize went to Watson, Crick, and Wilkins.\n\nThe discovery unlocked molecular biology, genetic engineering, DNA forensics, and the human genome. Every advance in biotechnology traces back to that Cambridge laboratory.', year: 1953, eraId: 'modern', latitude: 52.205, longitude: 0.121, category: 'discovery', locationName: 'Cambridge, England', imageUrl: 'https://images.unsplash.com/photo-1643780668909-580822430155?w=640&q=80&fit=crop', impactText: 'Rosalind Franklin\'s Photo 51 was shown to Watson without her consent. Watson later wrote that "my mouth fell open and my pulse began to race." She died before the Nobel was awarded.', modelUrl: 'https://sketchfab.com/models/360f24c050454356a23cc279fe2fbec0/embed?autostart=1&ui_theme=dark' },
  { id: 'cuban-missile-crisis', title: 'Cuban Missile Crisis', description: 'For thirteen days in October 1962, the world stood closer to nuclear annihilation than ever. Soviet missiles in Cuba could reach Washington in under thirteen minutes. Kennedy chose a naval blockade over the air strike his generals demanded.\n\nOn "Black Saturday," a Soviet submarine nearly launched a nuclear torpedo — only officer Vasili Arkhipov\'s refusal to authorize the launch prevented catastrophe. That evening, Kennedy secretly agreed to remove US missiles from Turkey.\n\nThe crisis led to the Moscow-Washington hotline and the first nuclear test ban treaty — small steps back from an abyss humanity came terrifyingly close to falling into.', year: 1962, eraId: 'modern', latitude: 23.113, longitude: -82.366, category: 'political', locationName: 'Havana, Cuba', imageUrl: 'https://images.unsplash.com/photo-1577942948749-a3dbb5c6db0a?w=640&q=80&fit=crop', impactText: 'Vasili Arkhipov may have single-handedly prevented nuclear war. When two officers wanted to launch a nuclear torpedo, a unanimous vote of three was required — Arkhipov alone voted no, saving perhaps hundreds of millions of lives.' },
  { id: 'civil-rights-act', title: 'Civil Rights Act of 1964', description: 'On July 2, 1964, President Johnson signed the most sweeping civil rights legislation since Reconstruction, outlawing discrimination based on race, color, religion, sex, or national origin. Jim Crow — legalized segregation for nearly a century — was dealt its death blow.\n\nThe bill survived a 54-day Senate filibuster — the longest in American history. Johnson assembled a bipartisan coalition to break it with a vote of 71-29.\n\nAs he signed, Johnson reportedly told an aide: "We have lost the South for a generation." He was right — the Democratic Party\'s Southern dominance collapsed. But the Act dismantled institutional segregation and opened doors closed for centuries.', year: 1964, eraId: 'modern', latitude: 38.897, longitude: -77.036, category: 'political', locationName: 'Washington, D.C., USA', imageUrl: 'https://images.unsplash.com/photo-1664946931630-65ead16cfe2f?w=640&q=80&fit=crop', impactText: 'Johnson used 75 different pens to sign the bill — giving them as souvenirs to supporters. The first pen went to Martin Luther King Jr., who kept it as one of his most prized possessions.' },
  { id: 'chernobyl-disaster', title: 'Chernobyl Nuclear Disaster', description: 'At 1:23 a.m. on April 26, 1986, reactor four at Chernobyl exploded, sending radioactive material 30 times more potent than Hiroshima across Europe. The 1,000-ton reactor lid was blown into the air. 28 workers died within months, their bodies destroyed by radiation.\n\nThe Soviet government initially covered it up — Sweden detected elevated radiation 1,100 km away. Pripyat\'s 49,000 residents weren\'t evacuated for 36 hours. Over 600,000 "liquidators" were sent in with inadequate protection.\n\nThe disaster shattered faith in Soviet competence and contributed to the USSR\'s collapse. Today the Exclusion Zone has become a wildlife sanctuary — wolves and horses roam abandoned Pripyat.', year: 1986, eraId: 'modern', latitude: 51.389, longitude: 30.098, category: 'natural', locationName: 'Pripyat, Ukraine', imageUrl: 'https://images.unsplash.com/photo-1543708819-a79b0bce3ea9?w=640&q=80&fit=crop', impactText: 'The "liquidators" who cleaned the roof were limited to 90-second shifts because of lethal radiation. They became "bio-robots" because actual robots malfunctioned in the intense fields.', modelUrl: 'https://sketchfab.com/models/cf34444de8804a1e9ec4a45520bc4e0c/embed?autostart=1&ui_theme=dark' },
  { id: 'mandela-freed', title: 'Nelson Mandela Released', description: 'On February 11, 1990, Nelson Mandela walked through prison gates after 27 years, 6 months, and 6 days behind bars — 18 on Robben Island breaking rocks in a lime quarry. An estimated 600 million people watched live on television.\n\nApartheid had ruled South Africa since 1948, denying 30 million Black citizens the vote. Mandela had been negotiating the end of apartheid from inside his cell since 1985.\n\nElected president in 1994 with 62% of the vote, he established the Truth and Reconciliation Commission, choosing forgiveness over vengeance. He served one term and voluntarily stepped down — cementing his legacy as one of the greatest moral figures of the 20th century.', year: 1990, eraId: 'modern', latitude: -33.924, longitude: 18.424, category: 'political', locationName: 'Cape Town, South Africa', imageUrl: 'https://images.unsplash.com/photo-1661112483600-bf3485542ec7?w=640&q=80&fit=crop', impactText: 'Mandela was offered his freedom at least twice on condition he renounce armed struggle. He refused each time. His 1985 response, read by his daughter to a stadium crowd, became legendary.', modelUrl: 'https://sketchfab.com/models/cab49d6967ae48b2adaa76a304c9347f/embed?autostart=1&ui_theme=dark' },
  { id: 'human-genome-project', title: 'Human Genome Project Completed', description: 'On April 14, 2003, scientists announced that 99% of the human genome had been sequenced with 99.99% accuracy — the culmination of a 13-year, $2.7 billion effort by 2,800 researchers across six countries. The 3.1 billion base pairs would fill 175,000 printed pages.\n\nHumans turned out to have only 20,000-25,000 genes — far fewer than the predicted 100,000, barely more than a roundworm. Over 98% of DNA is non-coding "junk" that has since been found to play crucial regulatory roles.\n\nThe project revealed all humans share 99.9% of their DNA, demolishing any biological basis for race. It enabled personalized medicine, CRISPR gene editing, and a revolution still unfolding.', year: 2003, eraId: 'modern', latitude: 38.996, longitude: -77.100, category: 'discovery', locationName: 'Bethesda, USA', imageUrl: 'https://images.unsplash.com/photo-1576089388754-68c54a863b60?w=640&q=80&fit=crop', impactText: 'The first genome cost $2.7 billion to sequence. By 2022, a human genome could be sequenced for under $200 — a cost reduction of over 10 million fold.', modelUrl: 'https://sketchfab.com/models/746f0754e7cb45a4b54840e1b858b01d/embed?autostart=1&ui_theme=dark' },
  { id: 'fukushima-disaster', title: 'Fukushima Nuclear Disaster', description: 'On March 11, 2011, a magnitude 9.0 earthquake — the most powerful ever recorded in Japan — generated 14-meter tsunami waves that breached the Fukushima Daiichi seawalls, flooding emergency generators. Three reactors melted down. Hydrogen explosions blew off reactor building roofs.\n\nApproximately 154,000 residents were evacuated. The "Fukushima 50" stayed behind in near-suicidal conditions, manually venting radioactive steam. Japan shut down all 54 nuclear reactors.\n\nThe cleanup will take 30-40 years and cost over $200 billion — the most expensive industrial disaster in history. The tsunami killed nearly 20,000 people and reshaped Japan\'s energy policy.', year: 2011, eraId: 'modern', latitude: 37.421, longitude: 141.032, category: 'natural', locationName: 'Fukushima, Japan', imageUrl: 'https://images.unsplash.com/photo-1591200834528-4050ce99fe78?w=640&q=80&fit=crop', impactText: 'The tsunami moved Honshu island 2.4 meters east and shifted Earth\'s axis by 10-25 cm. The earthquake shortened the length of a day by 1.8 microseconds.', modelUrl: 'https://sketchfab.com/models/a3ed95060a824c12a480e9e724ba3a83/embed?autostart=1&ui_theme=dark' },
  { id: 'mars-perseverance', title: 'Mars Perseverance Rover', description: 'On February 18, 2021, NASA\'s Perseverance rover touched down in Jezero Crater on Mars after "seven minutes of terror" — decelerating from 20,000 km/h to zero autonomously, since the 11-minute communication delay meant no human could intervene.\n\nThe rover carried 23 cameras, the Ingenuity helicopter (which achieved the first powered flight on another world), and a device that extracted oxygen from the Martian atmosphere for the first time.\n\nPerseverance\'s primary mission: searching for signs of ancient microbial life in a crater that once held a lake. It collected rock samples in titanium tubes for future return to Earth — the first material from another planet to be brought home.', year: 2021, eraId: 'modern', latitude: 28.572, longitude: -80.648, category: 'discovery', locationName: 'Cape Canaveral, USA', imageUrl: 'https://images.unsplash.com/photo-1614315517650-3771cf72d18a?w=640&q=80&fit=crop', impactText: 'Ingenuity was designed for 5 flights over 30 days. It flew 72 times over nearly 3 years, traveling 17 km across Mars — the first aircraft to achieve powered flight on another planet.', modelUrl: 'https://sketchfab.com/models/c1c94e1f69df45eeae4a0a1d0d27e85b/embed?autostart=1&ui_theme=dark' },
];

